insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (256, 25, 21, 34, 'سورة الفرقان ٢١ – ٣٤', '«وقدمنا إلى ما عملوا من عمل فجعلناه هباءً منثوراً»، و«ويوم يعضّ الظالم على يديه»، و«يا رب إن قومي اتخذوا هذا القرآن مهجوراً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 256) = $j$[{"lbl": "الآيات ٢١ – ٢٤", "q": "۞وَقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا لَوۡلَآ أُنزِلَ عَلَيۡنَا ٱلۡمَلَـٰٓئِكَةُ أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ وَعَتَوۡ عُتُوّٗا كَبِيرٗا ﴿٢١﴾ يَوۡمَ يَرَوۡنَ ٱلۡمَلَـٰٓئِكَةَ لَا بُشۡرَىٰ يَوۡمَئِذٖ لِّلۡمُجۡرِمِينَ وَيَقُولُونَ حِجۡرٗا مَّحۡجُورٗا ﴿٢٢﴾ وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا ﴿٢٣﴾ أَصۡحَٰبُ ٱلۡجَنَّةِ يَوۡمَئِذٍ خَيۡرٞ مُّسۡتَقَرّٗا وَأَحۡسَنُ مَقِيلٗا ﴿٢٤﴾", "w": [["لا يرجون لقاءنا", "المكذّبون بالبعث، إذ لقاء العبد ربه يكون يوم القيامة."], ["لولا أُنزل علينا الملائكة", "هلّا أُنزلت علينا الملائكة فتخبرنا بصدقك."], ["أو نرى ربنا", "فيخبرنا بأنك رسوله، وأن علينا أن نؤمن بك."], ["استكبروا في أنفسهم", "في شأن أنفسهم، ورأوا أنهم أكبر شيء وأعظمه غروراً."], ["وعتوا عتوّاً كبيراً", "طغوا طغياناً كبيراً حتى طالبوا بنزول الملائكة ورؤية الرب."], ["ويقولون حجراً محجوراً", "تقول لهم الملائكة: حراماً محرّماً عليكم البشرى."], ["وقدمنا إلى ما عملوا", "عمدنا إلى أعمالهم الفاسدة التي لم تكن على علم وإخلاص."], ["هباءً منثوراً", "الهباء: ما يُرى من غبار في شعاع الشمس الداخل من الكوى."], ["وأحسن مقيلاً", "المقيل: مكان الاستراحة في نصف النهار."]], "m": "ما زال السياق في أقوال المشركين: وقال المكذّبون بالبعث المنكرون للحياة الثانية: هلّا أُنزلت علينا الملائكة فتخبرنا بأن محمداً رسول، أو نرى ربنا فيأمرنا بالإيمان به! قال تعالى: لقد استكبروا في شأن أنفسهم ورأوا أنهم شيء كبير، وطغوا طغياناً كبيراً بقولهم هذا الذي لا داعي إليه إلا الكبر. يوم يرون الملائكة، يوم القيامة أو عند قبض أرواحهم، لا بشرى يومئذ للمجرمين، وتقول لهم الملائكة: حراماً محرّماً عليكم البشرى، بل هي للمؤمنين. وعمدنا إلى أعمالهم التي لم تقم على الإيمان والإخلاص والموافقة للشرع فصيّرناها كالغبار الذي يُرى في ضوء الشمس الداخل من نافذة، لا يُقبض باليد لدقّته، فلا ينتفعون منها بشيء. أصحاب الجنة الذين تأهّلوا لها بالإيمان والتقوى يومئذ خير مستقراً وأحسن مكان استراحة في نصف النهار، وفيه إشارة إلى أن الحساب قد ينقضي في نصف يوم، إذ الله سريع الحساب.", "h": ["بيان ما كان عليه غلاة المشركين من قريش من كبر وعتوّ وطغيان.", "إثبات رؤية الملائكة عند قبض الروح، ويوم القيامة.", "نفي البشرى عن المجرمين وإثباتها للمؤمنين المتقين.", "حبوط عمل المشركين وبطلانه، حيث لا ينتفعون بشيء منه البتة.", "انتهاء حساب المؤمنين قبل نصف يوم الحساب الذي مقداره خمسون ألف سنة."], "k": "«فجعلناه هباءً منثوراً»… عمل لم يكن خالصاً لا يزن شيئاً؛ فهل أنقّي نيّتي قبل أن أعمل؟"}, {"lbl": "الآيات ٢٥ – ٢٩", "q": "وَيَوۡمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلۡغَمَٰمِ وَنُزِّلَ ٱلۡمَلَـٰٓئِكَةُ تَنزِيلًا ﴿٢٥﴾ ٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ وَكَانَ يَوۡمًا عَلَى ٱلۡكَٰفِرِينَ عَسِيرٗا ﴿٢٦﴾ وَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلٗا ﴿٢٧﴾ يَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلٗا ﴿٢٨﴾ لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا ﴿٢٩﴾", "w": [["تشقّق السماء بالغمام", "عن الغمام، وهو سحاب أبيض رقيق."], ["الملك يومئذ الحق للرحمن", "الملك الحق لله، ولم يبق لملوك الأرض ومالكيها ملك."], ["على الكافرين عسيراً", "صعباً شديداً."], ["يعضّ الظالم على يديه", "ندماً وأسفاً على ما فرّط في جنب الله."], ["سبيلاً", "طريقاً إلى النجاة بالإيمان والطاعة."], ["لم أتخذ فلاناً خليلاً", "صديقاً ودوداً، وهو أُبيّ بن خلف."], ["لقد أضلّني عن الذكر", "عن القرآن وما يدعو إليه من الإيمان والتوحيد والعمل الصالح."], ["وكان الشيطان", "شيطان الجن وشيطان الإنس."], ["خذولاً", "يورّطه ثم يتخلّى عنه."]], "m": "ما زال السياق في عرض مظاهر القيامة: واذكر يوم تشقّق السماء عن الغمام، ونُزّل الملائكة تنزيلاً لمجيء الرب تبارك وتعالى لفصل القضاء، الملك يومئذ الحق للرحمن لا لغيره من ملوك الدنيا، وكان يوماً على الكافرين عسيراً لا يُطاق. ويوم يعضّ الظالم على يديه تندّماً وتحسّراً على تفريطه في الإيمان وصالح الأعمال، يقول: يا ليتني اتخذت مع الرسول طريقاً إلى النجاة، يا ويلتى، يا هلكتي احضري، ليتني لم أتخذ فلاناً خليلاً، شيطان الإنس أو الجن الذي صافاه في الدنيا فغرّر به، لقد أضلّني عن القرآن بعد إذ جاءني من ربي، وكان الشيطان للإنسان خذولاً، يورّطه ثم يتخلّى عنه.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحوالها وبعض أهوالها.", "إثبات مجيء الرب تبارك وتعالى لفصل القضاء يوم القيامة.", "تندّم الظلمة وتحسّرهم على ما فاتهم من الإيمان والطاعة لله ورسوله.", "بيان سوء عاقبة موالاة شياطين الإنس والجن وطاعتهم في معصية الله ورسوله.", "تقرير مبدأ أن العبرة بعموم اللفظ لا بخصوص السبب، إذ نزلت في عقبة بن أبي معيط، آمن ثم لامه أُبيّ بن خلف فارتدّ."], "k": "«يا ليتني لم أتخذ فلاناً خليلاً»… صحبتي اليوم، هل ستكون حسرة أم نجاة يومها؟"}, {"lbl": "الآيات ٣٠ – ٣٤", "q": "وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوۡمِي ٱتَّخَذُواْ هَٰذَا ٱلۡقُرۡءَانَ مَهۡجُورٗا ﴿٣٠﴾ وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا ﴿٣١﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلٗا ﴿٣٢﴾ وَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا ﴿٣٣﴾ ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ سَبِيلٗا ﴿٣٤﴾", "w": [["مهجوراً", "شيئاً متروكاً لا يُلتفت إليه."], ["هادياً ونصيراً", "هادياً لك إلى طريق الفوز، وناصراً لك على كل أعدائك."], ["جملة واحدة", "كما نزلت التوراة والإنجيل والزبور دفعة واحدة."], ["لنثبّت به فؤادك", "نقوّي قلبك لتتحمّل أعباء الرسالة وإبلاغها."], ["ورتّلناه ترتيلاً", "أنزلناه شيئاً فشيئاً، آيات بعد آيات، ليتيسّر فهمه وحفظه."], ["شرّ مكاناً", "منزلاً، وهو جهنم والعياذ بالله منها."]], "m": "وقال الرسول: يا رب إن قومي اتخذوا هذا القرآن مهجوراً، شكوى منه ﷺ بقومه إلى ربه، وهجرهم للقرآن تركهم سماعه وتفهّمه والعمل به. وكما جعلنا لك أعداء من مجرمي قومك جعلنا لكل نبي عدواً من المجرمين، فاصبر حتى تبلّغ رسالتك، وكفى بربك هادياً ونصيراً. وقال الذين كفروا تعنّتاً: هلّا نُزّل عليه القرآن جملة واحدة كالتوراة والإنجيل؟ فردّ تعالى: كذلك أنزلناه مفرّقاً لنثبّت به فؤادك، فهو كالغيث كلما نزل أحيا موات الأرض، ونزوله مرة بعد مرة أنفع، ورتّلناه ترتيلاً ليتيسّر حفظه وفهمه والعمل به. ولا يأتونك بمثل أو شبهة إلا جئناك بالحق الذي يبطلها وبأحسن تفسير لما اشتبه عليهم. الذين يُحشرون على وجوههم إلى جهنم، تسحبهم الملائكة لإجرامهم، أولئك شرّ مكاناً يوم القيامة وأضلّ سبيلاً في الدنيا.", "h": ["شهادة الرسول ﷺ على من هجروا القرآن الكريم فلم يسمعوه ولم يتفهّموه ولم يعملوا به، وشكواه إياهم إلى الله عز وجل.", "بيان سنة الله في العباد، وهي أنه ما من نبي ولا هادٍ إلا وله عدو من الناس، لتعارض الحق مع الباطل.", "بيان الحكمة في نزول القرآن منجّماً شيئاً فشيئاً.", "بيان أن المجرمين يُحشرون على وجوههم لا على أرجلهم إلى جهنم إهانة لهم."], "k": "«إن قومي اتخذوا هذا القرآن مهجوراً»… سماعاً أو تدبّراً أو عملاً؛ في أي هجر أقع أنا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 256;
insert into public.tdb_cards(topic, i, body) select 256, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١ – ٢٤", "q": "۞وَقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا لَوۡلَآ أُنزِلَ عَلَيۡنَا ٱلۡمَلَـٰٓئِكَةُ أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ وَعَتَوۡ عُتُوّٗا كَبِيرٗا ﴿٢١﴾ يَوۡمَ يَرَوۡنَ ٱلۡمَلَـٰٓئِكَةَ لَا بُشۡرَىٰ يَوۡمَئِذٖ لِّلۡمُجۡرِمِينَ وَيَقُولُونَ حِجۡرٗا مَّحۡجُورٗا ﴿٢٢﴾ وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا ﴿٢٣﴾ أَصۡحَٰبُ ٱلۡجَنَّةِ يَوۡمَئِذٍ خَيۡرٞ مُّسۡتَقَرّٗا وَأَحۡسَنُ مَقِيلٗا ﴿٢٤﴾", "w": [["لا يرجون لقاءنا", "المكذّبون بالبعث، إذ لقاء العبد ربه يكون يوم القيامة."], ["لولا أُنزل علينا الملائكة", "هلّا أُنزلت علينا الملائكة فتخبرنا بصدقك."], ["أو نرى ربنا", "فيخبرنا بأنك رسوله، وأن علينا أن نؤمن بك."], ["استكبروا في أنفسهم", "في شأن أنفسهم، ورأوا أنهم أكبر شيء وأعظمه غروراً."], ["وعتوا عتوّاً كبيراً", "طغوا طغياناً كبيراً حتى طالبوا بنزول الملائكة ورؤية الرب."], ["ويقولون حجراً محجوراً", "تقول لهم الملائكة: حراماً محرّماً عليكم البشرى."], ["وقدمنا إلى ما عملوا", "عمدنا إلى أعمالهم الفاسدة التي لم تكن على علم وإخلاص."], ["هباءً منثوراً", "الهباء: ما يُرى من غبار في شعاع الشمس الداخل من الكوى."], ["وأحسن مقيلاً", "المقيل: مكان الاستراحة في نصف النهار."]], "m": "ما زال السياق في أقوال المشركين: وقال المكذّبون بالبعث المنكرون للحياة الثانية: هلّا أُنزلت علينا الملائكة فتخبرنا بأن محمداً رسول، أو نرى ربنا فيأمرنا بالإيمان به! قال تعالى: لقد استكبروا في شأن أنفسهم ورأوا أنهم شيء كبير، وطغوا طغياناً كبيراً بقولهم هذا الذي لا داعي إليه إلا الكبر. يوم يرون الملائكة، يوم القيامة أو عند قبض أرواحهم، لا بشرى يومئذ للمجرمين، وتقول لهم الملائكة: حراماً محرّماً عليكم البشرى، بل هي للمؤمنين. وعمدنا إلى أعمالهم التي لم تقم على الإيمان والإخلاص والموافقة للشرع فصيّرناها كالغبار الذي يُرى في ضوء الشمس الداخل من نافذة، لا يُقبض باليد لدقّته، فلا ينتفعون منها بشيء. أصحاب الجنة الذين تأهّلوا لها بالإيمان والتقوى يومئذ خير مستقراً وأحسن مكان استراحة في نصف النهار، وفيه إشارة إلى أن الحساب قد ينقضي في نصف يوم، إذ الله سريع الحساب.", "h": ["بيان ما كان عليه غلاة المشركين من قريش من كبر وعتوّ وطغيان.", "إثبات رؤية الملائكة عند قبض الروح، ويوم القيامة.", "نفي البشرى عن المجرمين وإثباتها للمؤمنين المتقين.", "حبوط عمل المشركين وبطلانه، حيث لا ينتفعون بشيء منه البتة.", "انتهاء حساب المؤمنين قبل نصف يوم الحساب الذي مقداره خمسون ألف سنة."], "k": "«فجعلناه هباءً منثوراً»… عمل لم يكن خالصاً لا يزن شيئاً؛ فهل أنقّي نيّتي قبل أن أعمل؟"}, {"lbl": "الآيات ٢٥ – ٢٩", "q": "وَيَوۡمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلۡغَمَٰمِ وَنُزِّلَ ٱلۡمَلَـٰٓئِكَةُ تَنزِيلًا ﴿٢٥﴾ ٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ وَكَانَ يَوۡمًا عَلَى ٱلۡكَٰفِرِينَ عَسِيرٗا ﴿٢٦﴾ وَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلٗا ﴿٢٧﴾ يَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلٗا ﴿٢٨﴾ لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا ﴿٢٩﴾", "w": [["تشقّق السماء بالغمام", "عن الغمام، وهو سحاب أبيض رقيق."], ["الملك يومئذ الحق للرحمن", "الملك الحق لله، ولم يبق لملوك الأرض ومالكيها ملك."], ["على الكافرين عسيراً", "صعباً شديداً."], ["يعضّ الظالم على يديه", "ندماً وأسفاً على ما فرّط في جنب الله."], ["سبيلاً", "طريقاً إلى النجاة بالإيمان والطاعة."], ["لم أتخذ فلاناً خليلاً", "صديقاً ودوداً، وهو أُبيّ بن خلف."], ["لقد أضلّني عن الذكر", "عن القرآن وما يدعو إليه من الإيمان والتوحيد والعمل الصالح."], ["وكان الشيطان", "شيطان الجن وشيطان الإنس."], ["خذولاً", "يورّطه ثم يتخلّى عنه."]], "m": "ما زال السياق في عرض مظاهر القيامة: واذكر يوم تشقّق السماء عن الغمام، ونُزّل الملائكة تنزيلاً لمجيء الرب تبارك وتعالى لفصل القضاء، الملك يومئذ الحق للرحمن لا لغيره من ملوك الدنيا، وكان يوماً على الكافرين عسيراً لا يُطاق. ويوم يعضّ الظالم على يديه تندّماً وتحسّراً على تفريطه في الإيمان وصالح الأعمال، يقول: يا ليتني اتخذت مع الرسول طريقاً إلى النجاة، يا ويلتى، يا هلكتي احضري، ليتني لم أتخذ فلاناً خليلاً، شيطان الإنس أو الجن الذي صافاه في الدنيا فغرّر به، لقد أضلّني عن القرآن بعد إذ جاءني من ربي، وكان الشيطان للإنسان خذولاً، يورّطه ثم يتخلّى عنه.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحوالها وبعض أهوالها.", "إثبات مجيء الرب تبارك وتعالى لفصل القضاء يوم القيامة.", "تندّم الظلمة وتحسّرهم على ما فاتهم من الإيمان والطاعة لله ورسوله.", "بيان سوء عاقبة موالاة شياطين الإنس والجن وطاعتهم في معصية الله ورسوله.", "تقرير مبدأ أن العبرة بعموم اللفظ لا بخصوص السبب، إذ نزلت في عقبة بن أبي معيط، آمن ثم لامه أُبيّ بن خلف فارتدّ."], "k": "«يا ليتني لم أتخذ فلاناً خليلاً»… صحبتي اليوم، هل ستكون حسرة أم نجاة يومها؟"}, {"lbl": "الآيات ٣٠ – ٣٤", "q": "وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوۡمِي ٱتَّخَذُواْ هَٰذَا ٱلۡقُرۡءَانَ مَهۡجُورٗا ﴿٣٠﴾ وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا ﴿٣١﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلٗا ﴿٣٢﴾ وَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا ﴿٣٣﴾ ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ سَبِيلٗا ﴿٣٤﴾", "w": [["مهجوراً", "شيئاً متروكاً لا يُلتفت إليه."], ["هادياً ونصيراً", "هادياً لك إلى طريق الفوز، وناصراً لك على كل أعدائك."], ["جملة واحدة", "كما نزلت التوراة والإنجيل والزبور دفعة واحدة."], ["لنثبّت به فؤادك", "نقوّي قلبك لتتحمّل أعباء الرسالة وإبلاغها."], ["ورتّلناه ترتيلاً", "أنزلناه شيئاً فشيئاً، آيات بعد آيات، ليتيسّر فهمه وحفظه."], ["شرّ مكاناً", "منزلاً، وهو جهنم والعياذ بالله منها."]], "m": "وقال الرسول: يا رب إن قومي اتخذوا هذا القرآن مهجوراً، شكوى منه ﷺ بقومه إلى ربه، وهجرهم للقرآن تركهم سماعه وتفهّمه والعمل به. وكما جعلنا لك أعداء من مجرمي قومك جعلنا لكل نبي عدواً من المجرمين، فاصبر حتى تبلّغ رسالتك، وكفى بربك هادياً ونصيراً. وقال الذين كفروا تعنّتاً: هلّا نُزّل عليه القرآن جملة واحدة كالتوراة والإنجيل؟ فردّ تعالى: كذلك أنزلناه مفرّقاً لنثبّت به فؤادك، فهو كالغيث كلما نزل أحيا موات الأرض، ونزوله مرة بعد مرة أنفع، ورتّلناه ترتيلاً ليتيسّر حفظه وفهمه والعمل به. ولا يأتونك بمثل أو شبهة إلا جئناك بالحق الذي يبطلها وبأحسن تفسير لما اشتبه عليهم. الذين يُحشرون على وجوههم إلى جهنم، تسحبهم الملائكة لإجرامهم، أولئك شرّ مكاناً يوم القيامة وأضلّ سبيلاً في الدنيا.", "h": ["شهادة الرسول ﷺ على من هجروا القرآن الكريم فلم يسمعوه ولم يتفهّموه ولم يعملوا به، وشكواه إياهم إلى الله عز وجل.", "بيان سنة الله في العباد، وهي أنه ما من نبي ولا هادٍ إلا وله عدو من الناس، لتعارض الحق مع الباطل.", "بيان الحكمة في نزول القرآن منجّماً شيئاً فشيئاً.", "بيان أن المجرمين يُحشرون على وجوههم لا على أرجلهم إلى جهنم إهانة لهم."], "k": "«إن قومي اتخذوا هذا القرآن مهجوراً»… سماعاً أو تدبّراً أو عملاً؛ في أي هجر أقع أنا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (257, 25, 35, 44, 'سورة الفرقان ٣٥ – ٤٤', 'هلاك المكذّبين: قوم موسى ونوح وعاد وثمود وأصحاب الرسّ، و«أرأيت من اتخذ إلهه هواه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 257) = $j$[{"lbl": "الآيات ٣٥ – ٤٠", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرٗا ﴿٣٥﴾ فَقُلۡنَا ٱذۡهَبَآ إِلَى ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا فَدَمَّرۡنَٰهُمۡ تَدۡمِيرٗا ﴿٣٦﴾ وَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ وَأَعۡتَدۡنَا لِلظَّـٰلِمِينَ عَذَابًا أَلِيمٗا ﴿٣٧﴾ وَعَادٗا وَثَمُودَاْ وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرٗا ﴿٣٨﴾ وَكُلّٗا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا ﴿٣٩﴾ وَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورٗا ﴿٤٠﴾", "w": [["الكتاب", "التوراة."], ["وزيراً", "معيناً."], ["إلى القوم الذين كذّبوا", "هم فرعون وآله."], ["لما كذّبوا الرسل", "أي نوحاً ﵇، ومن كذّب رسولاً فكأنما كذّب الرسل جميعاً."], ["وجعلناهم للناس آية", "علامة على قدرتنا في إهلاك الظالمين وعبرة."], ["وأصحاب الرسّ", "الرسّ: بئر رسّ فيها قوم نبيّهم، أي رموه فيها ودسّوه في التراب."], ["وقروناً بين ذلك كثيراً", "ودمّرنا بين من ذكرنا من الأمم قروناً كثيرة."], ["تبّرنا تتبيراً", "دمّرناهم تدميراً."], ["التي أُمطرت مطر السوء", "هي سدوم قرية قوم لوط."], ["لا يرجون نشوراً", "لا يؤمنون بالبعث والجزاء الآخر."]], "m": "هذا شروع في عرض أمم كذّبت رسلها فأهلكها الله، عظة للمشركين: ولقد آتينا موسى التوراة وجعلنا معه أخاه هارون معيناً، فقلنا: اذهبا إلى القوم الذين كذّبوا بآياتنا، فرعون وملئه، فكذّبوهما فدمّرناهم بالغرق. وقوم نوح لما كذّبوا الرسل أغرقناهم بالطوفان وجعلناهم للناس عبرة، وأعتدنا للظالمين في الآخرة عذاباً أليماً. وعاداً وثمود وأصحاب الرسّ وقروناً بين ذلك كثيراً أهلكناهم، وكلاً ضربنا له الأمثال إقامة للحجة، فما أهلكناهم إلا بعد الإنذار والإعذار، وكلاً تبّرنا تتبيراً. ولقد مرّ كفار قريش في سفرهم إلى الشام على قرى قوم لوط التي أمطرت الحجارة، أفلم يكونوا يرونها فيعتبروا؟ بل كانوا لا يرجون نشوراً، فالذي لا يرجو أن يُبعث ويُحاسب لا يؤمن ولا يستقيم.", "h": ["بيان سنة الله تعالى في إهلاك الأمم بعد الإنذار والإعذار إليها.", "بيان عاقبة المكذّبين وما حلّ بهم من دمار وعذاب.", "بيان علّة تكذيب قريش للرسول ﷺ وما جاء به، وهي تكذيبهم بالبعث والجزاء، فلهذا لم تنفعهم المواعظ ولم تؤثّر فيهم العبر."], "k": "«أفلم يكونوا يرونها»… مرّوا على العبرة ولم يعتبروا؛ فأي عبرة مررت بها اليوم؟"}, {"lbl": "الآيات ٤١ – ٤٤", "q": "وَإِذَا رَأَوۡكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا ﴿٤١﴾ إِن كَادَ لَيُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡلَآ أَن صَبَرۡنَا عَلَيۡهَاۚ وَسَوۡفَ يَعۡلَمُونَ حِينَ يَرَوۡنَ ٱلۡعَذَابَ مَنۡ أَضَلُّ سَبِيلًا ﴿٤٢﴾ أَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا ﴿٤٣﴾ أَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ﴿٤٤﴾", "w": [["إن يتخذونك", "ما يتخذونك."], ["إلا هزواً", "مهزوءاً به."], ["أهذا الذي بعث الله رسولاً", "في دعواه، والاستفهام للتهكّم."], ["إن كاد ليضلّنا عن آلهتنا", "قارب أن يصرفنا عن آلهتنا."], ["لولا أن صبرنا عليها", "لصرفنا عنها."], ["أرأيت من اتخذ إلهه هواه", "أخبرني عمن جعل هواه معبوده فأطاعه، فهل تقدر على هدايته؟"], ["إن هم إلا كالأنعام", "ما هم إلا كالأنعام في عدم الوعي والإدراك."]], "m": "يخبر تعالى رسوله أن المشركين إذا رأوه في مجلس أو طريق ما يتخذونه إلا مهزوءاً به احتقاراً، يقولون: أهذا الذي بعث الله رسولاً؟ إن كاد ليصرفنا عن عبادة آلهتنا لولا أن صبرنا وثبتنا عليها، وهذا ناتج عن ظلمة الكفر والتكذيب بالبعث. وسوف يعلمون حين يعاينون العذاب من أضلّ سبيلاً، هم أم الرسول والمؤمنون، وقد حلّ بهم في بدر. أرأيت من جعل معبوده هواه، كلما اشتهى شيئاً فعله بلا عقل ولا رويّة، فقد يكون لأحدهم حجر يعبده فإذا رأى حجراً أحسن منه عبده وترك الأول، أفأنت تكون عليه حفيظاً تتولّى هدايته؟ أم تحسب أن أكثرهم يسمعون أو يعقلون؟ إن هم إلا كالأنعام، بل هم أضلّ سبيلاً، إذ الأنعام تعرف طريق مرعاها وتستجيب لنداء راعيها، وهم جهلوا ربهم ولم يستجيبوا لنداء رسوله.", "h": ["بيان ما كان الرسول ﷺ يلاقي في سبيل الدعوة من سخرية واستهزاء.", "يتجاهل الإنسان الضال الحق وينكره حتى إذا عاين العذاب عرف ما كان ينكر.", "هداية الإنسان ممكنة، حتى إذا كفر بعقله وآمن بشهوته وعبد هواه تعذّرت هدايته وأصبح أضلّ من الحيوان وأكثر خسراناً منه."], "k": "«أرأيت من اتخذ إلهه هواه»… في أي أمر يأمرني هواي فأطيعه دون نظر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 257;
