insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (258, 25, 45, 62, 'سورة الفرقان ٤٥ – ٦٢', '«ألم تر إلى ربك كيف مدّ الظل»، و«وهو الذي مرج البحرين»، و«وتوكّل على الحي الذي لا يموت»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 258) = $j$[{"lbl": "الآيات ٤٥ – ٥٠", "q": "أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا ﴿٤٥﴾ ثُمَّ قَبَضۡنَٰهُ إِلَيۡنَا قَبۡضٗا يَسِيرٗا ﴿٤٦﴾ وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِبَاسٗا وَٱلنَّوۡمَ سُبَاتٗا وَجَعَلَ ٱلنَّهَارَ نُشُورٗا ﴿٤٧﴾ وَهُوَ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا ﴿٤٨﴾ لِّنُحۡـِۧيَ بِهِۦ بَلۡدَةٗ مَّيۡتٗا وَنُسۡقِيَهُۥ مِمَّا خَلَقۡنَآ أَنۡعَٰمٗا وَأَنَاسِيَّ كَثِيرٗا ﴿٤٩﴾ وَلَقَدۡ صَرَّفۡنَٰهُ بَيۡنَهُمۡ لِيَذَّكَّرُواْ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا ﴿٥٠﴾", "w": [["ألم تر إلى ربك كيف مدّ الظل", "ألم تنظر إلى صنيع ربك في الظل كيف بسطه."], ["ولو شاء لجعله ساكناً", "ثابتاً على حاله في الطول والامتداد لا يقصر."], ["ثم جعلنا الشمس عليه دليلاً", "علامة على وجوده، إذ لولا الشمس لما عُرف الظل."], ["ثم قبضناه إلينا قبضاً يسيراً", "أزلناه بضوء الشمس على مهل جزءاً فجزءاً."], ["الليل لباساً", "يستركم بظلامه كما يستركم اللباس."], ["والنوم سباتاً", "راحة لأبدانكم من عناء عمل النهار."], ["وجعل النهار نشوراً", "حياة، إذ النوم بالليل كالموت والانتشار بالنهار كالحياة."], ["بشراً بين يدي رحمته", "مبشّرة بالمطر قبل نزوله، والمطر هو الرحمة."], ["ماءً طهوراً", "تتطهّرون به من الأحداث والأوساخ."], ["أنعاماً وأناسيّ كثيراً", "حيواناً وأناساً كثيرين."], ["ولقد صرّفناه بينهم", "المطر، ينزل بأرض قوم ولا ينزل بأخرى لحكم عالية."], ["ليذّكّروا", "فيذكروا فضل الله عليهم فيشكروا ويوحّدوا."], ["فأبى أكثر الناس إلا كفوراً", "جحوداً للنعمة."]], "m": "هذا شروع في ذكر مجموعة من أدلة التوحيد، وهي مظاهر لربوبية الله المقتضية لألوهيته. أولاً الظل: مدّه الخالق وبسطه من وقت الإسفار، ثم تطلع الشمس فيأخذ في الانكماش شيئاً فشيئاً حتى تقف في كبد السماء، ثم يفيء ويطول تدريجياً لتُعرف به ساعات النهار وأوقات الصلوات، ثم يُقبض قبضاً خفياً سريعاً حين تغرب الشمس، ولو شاء لجعله ساكناً لا يبارح. ثانياً الليل والنهار: جعل الليل ساتراً كاللباس، والنوم قطعاً للعمل تحصل به راحة الأبدان، والنهار حياة بعد وفاة النوم ينتشر فيه الناس لطلب الرزق. ثالثاً إرسال الرياح مبشّرات بالمطر الذي هو الرحمة. رابعاً إنزال الماء الطهور ليحيي به الأرض الميتة ويسقيه الأنعام والأناسيّ الكثيرين. خامساً تصريف المطر بين الناس، يُمطر إقليم ويُحرم آخر حسب الحكمة الإلهية، ليذكروا فيشكروا، فأبى أكثر الناس إلا كفوراً وجحوداً، وهو أمر يقتضي التعجّب.", "h": ["عرض الأدلة الحسية على وجوب عبادة الله تعالى وتوحيده فيها، ووجوب الإيمان بالبعث والجزاء.", "بيان فائدة الظل، إذ به تُعرف ساعات النهار، وبه يُعرف وقت صلاة الظهر والعصر.", "الماء الطهور هو الباقي على أصل خلقته، فلم يخالطه شيء يغيّر طعمه أو لونه أو ريحه، وبه تُرفع الأحداث وتُغسل النجاسات."], "k": "«ثم جعلنا الشمس عليه دليلاً»… ظلٌّ يطول ويقصر يذكّرني بمواقيت صلاتي؛ فهل ألتفت إليه؟"}, {"lbl": "الآيات ٥١ – ٥٦", "q": "وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِي كُلِّ قَرۡيَةٖ نَّذِيرٗا ﴿٥١﴾ فَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا ﴿٥٢﴾ ۞وَهُوَ ٱلَّذِي مَرَجَ ٱلۡبَحۡرَيۡنِ هَٰذَا عَذۡبٞ فُرَاتٞ وَهَٰذَا مِلۡحٌ أُجَاجٞ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخٗا وَحِجۡرٗا مَّحۡجُورٗا ﴿٥٣﴾ وَهُوَ ٱلَّذِي خَلَقَ مِنَ ٱلۡمَآءِ بَشَرٗا فَجَعَلَهُۥ نَسَبٗا وَصِهۡرٗاۗ وَكَانَ رَبُّكَ قَدِيرٗا ﴿٥٤﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرٗا ﴿٥٥﴾ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا ﴿٥٦﴾", "w": [["ولو شئنا لبعثنا في كل قرية نذيراً", "رسولاً ينذر أهلها، ولكن جعلناك رسول القرى كلها."], ["وجاهدهم به", "بالقرآن، وكله حجج وبيّنات."], ["مرج البحرين", "أرسلهما متجاورين: الملح والعذب."], ["وجعل بينهما برزخاً", "حاجزاً بين الملح منهما والعذب."], ["وحجراً محجوراً", "سدّاً مانعاً، فلا يحلو الملح ولا يملح العذب."], ["خلق من الماء بشراً", "خلق الإنسان من النطفة."], ["فجعله نسباً وصهراً", "ذكوراً يُنسب إليهم، وإناثاً يُصاهر بهن."], ["ما لا ينفعهم ولا يضرّهم", "أصناماً لا تنفع ولا تضر."], ["وكان الكافر على ربه ظهيراً", "معيناً للشيطان على معصية الرحمن."]], "m": "ولو شئنا لبعثنا في كل مدينة رسولاً ينذر أهلها، ولكنا لم نشأ لحكمة، وهي أن تكون أيها الرسول أفضل الرسل وأعظمهم منزلة وثواباً، فكنت رسول القرى كلها، فاصبر وتحمّل، فلا تطع الكافرين في أي أمر أرادوه منك، وجاهدهم بالقرآن جهاداً كبيراً. ثم واصل تعالى ذكر مظاهر ربوبيته: وهو الذي أرسل البحرين الملح والعذب متجاورين، هذا عذب فرات سائغ شرابه، وهذا ملح أجاج لا يُشرب، وجعل بينهما حاجزاً مانعاً من اختلاطهما مع وجودهما في مكان واحد. وهو الذي خلق من النطفة الإنسان، فجعله ذكوراً يُنسب إليهم وإناثاً يُصاهر بهن، وكان ربك قديراً على ما يريد. هذه مظاهر الربوبية المقتضية لعبادته وحده، والمشركون يعبدون من دونه أصناماً لا تنفعهم إن عبدوها ولا تضرهم إن تركوها، فيعبدون الشيطان الذي زيّن لهم ذلك، فكان الكافر معيناً للشيطان على الرحمن. وما أرسلناك إلا مبشّراً للمؤمنين بالجنة ونذيراً للكافرين بالنار، أما هداية القلوب فإلى الله.", "h": ["الإشارة إلى الحكمة في عدم تعدّد الرسل في زمن البعثة المحمدية، والاكتفاء بالرسول ﷺ.", "حرمة طاعة الكافرين في أمور الدين والشرع.", "من الجهاد جهاد الكفار والملاحدة بالحجج القرآنية والآيات التنزيلية.", "مظاهر العلم والقدرة الإلهية في عدم اختلاط البحرين مع وجودهما في مكان واحد، وفي خلق الإنسان من ماء وجعله ذكراً وأنثى للتناسل وحفظ النوع.", "التنديد بالكافرين الذين يكونون عوناً للشيطان على الرحمن."], "k": "«وجاهدهم به جهاداً كبيراً»… القرآن نفسه هو السلاح؛ فكم آية أحملها في قلبي حجّةً للحق؟"}, {"lbl": "الآيات ٥٧ – ٦٢", "q": "قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ﴿٥٧﴾ وَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا ﴿٥٨﴾ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَٰنُ فَسۡـَٔلۡ بِهِۦ خَبِيرٗا ﴿٥٩﴾ وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا۩ ﴿٦٠﴾ تَبَارَكَ ٱلَّذِي جَعَلَ فِي ٱلسَّمَآءِ بُرُوجٗا وَجَعَلَ فِيهَا سِرَٰجٗا وَقَمَرٗا مُّنِيرٗا ﴿٦١﴾ وَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا ﴿٦٢﴾", "w": [["ما أسألكم عليه من أجر", "على البلاغ أجراً أتقاضاه منكم."], ["سبيلاً", "طريقاً يصل به إلى مرضاة ربه، وذلك بإنفاق ماله في سبيله."], ["وسبّح بحمده", "قل: سبحان الله وبحمده."], ["في ستة أيام", "من أيام الدنيا."], ["ثم استوى على العرش", "العرش سرير الملك، والاستواء معلوم، والكيف مجهول."], ["فاسأل به خبيراً", "اسأل بالرحمن خبيراً يُنبئك بعظمته."], ["وزادهم نفوراً", "زادهم القول لهم: اسجدوا للرحمن، نفوراً من الإيمان."], ["جعل في السماء بروجاً", "منازل الكواكب السيّارة، وهي اثنا عشر برجاً."], ["سراجاً", "شمساً."], ["خلفة", "يخلف أحدهما الآخر."], ["لمن أراد أن يذّكّر", "ما فاته في أحدهما فيفعله في الآخر."], ["أو أراد شكوراً", "شكراً لنعم ربه بالصيام والصلاة فيهما."]], "m": "بعد هذا العرض العظيم لمظاهر الربوبية أمر الله رسوله أن يقول للمشركين: ما أسألكم على هذا البيان أجراً، لكن من شاء أن ينفق من ماله في وجوه البر يتقرّب به إلى ربه فله ذلك، ليتخذ به طريقاً إلى رضاه. وأمره أن يمضي في دعوته متوكلاً على الحي الذي لا يموت، وغيره يموت، وأن يستعين على صبره بالتسبيح، وهو أمر بالذكر والصلاة وسائر العبادات فإنها العون الكبير على الثبات، وكفى بالله بذنوب عباده خبيراً فلا تحزن عليهم. ثم أثنى تعالى على نفسه: الذي خلق السماوات والأرض وما بينهما في ستة أيام، ثم استوى على العرش استواءً يليق بجلاله، الرحمن الذي عمّت رحمته العالمين، فاسأل به خبيراً بخلقه. وإذا قال لهم الرسول: اسجدوا للرحمن، قالوا متجاهلين: وما الرحمن؟ أنسجد لما تأمرنا؟ وزادهم ذلك نفوراً. تبارك الذي جعل في السماء بروجاً هي منازل الكواكب، وجعل فيها شمساً سراجاً وقمراً منيراً، وهو الذي جعل الليل والنهار يخلف أحدهما الآخر، فمن نسي عملاً بالنهار ذكره بالليل فعمله، ومن أراد أن يشكر فالليل للتهجّد والقيام والنهار للصيام والجهاد.", "h": ["الداعي إلى الله ينبغي ألا يأخذ أجراً ممن يدعوهم إلى الله تعالى، ومن أراد أن يتطوّع من نفسه فينفق في سبيل الله فذلك له.", "وجوب التوكّل على الله، فإنه الحي الذي لا يموت وغيره يموت.", "وجوب التسبيح والذكر والعبادة، وهذه هي زاد العبد وعدّته وعونه.", "مشروعية السجود عند قوله تعالى: «وزادهم نفوراً» للقارئ والمستمع.", "صفة استواء الرحمن على عرشه، فيجب الإيمان بها على ما يليق بجلال الله وكماله.", "الترغيب في الذكر والشكر، واغتنام الفرص للعبادة والطاعة."], "k": "«لمن أراد أن يذّكّر أو أراد شكوراً»… ما فاتني نهاراً لم يفت؛ فهل أجعل ليلتي فرصة للتدارك؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 258;
insert into public.tdb_cards(topic, i, body) select 258, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٥ – ٥٠", "q": "أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا ﴿٤٥﴾ ثُمَّ قَبَضۡنَٰهُ إِلَيۡنَا قَبۡضٗا يَسِيرٗا ﴿٤٦﴾ وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِبَاسٗا وَٱلنَّوۡمَ سُبَاتٗا وَجَعَلَ ٱلنَّهَارَ نُشُورٗا ﴿٤٧﴾ وَهُوَ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا ﴿٤٨﴾ لِّنُحۡـِۧيَ بِهِۦ بَلۡدَةٗ مَّيۡتٗا وَنُسۡقِيَهُۥ مِمَّا خَلَقۡنَآ أَنۡعَٰمٗا وَأَنَاسِيَّ كَثِيرٗا ﴿٤٩﴾ وَلَقَدۡ صَرَّفۡنَٰهُ بَيۡنَهُمۡ لِيَذَّكَّرُواْ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا ﴿٥٠﴾", "w": [["ألم تر إلى ربك كيف مدّ الظل", "ألم تنظر إلى صنيع ربك في الظل كيف بسطه."], ["ولو شاء لجعله ساكناً", "ثابتاً على حاله في الطول والامتداد لا يقصر."], ["ثم جعلنا الشمس عليه دليلاً", "علامة على وجوده، إذ لولا الشمس لما عُرف الظل."], ["ثم قبضناه إلينا قبضاً يسيراً", "أزلناه بضوء الشمس على مهل جزءاً فجزءاً."], ["الليل لباساً", "يستركم بظلامه كما يستركم اللباس."], ["والنوم سباتاً", "راحة لأبدانكم من عناء عمل النهار."], ["وجعل النهار نشوراً", "حياة، إذ النوم بالليل كالموت والانتشار بالنهار كالحياة."], ["بشراً بين يدي رحمته", "مبشّرة بالمطر قبل نزوله، والمطر هو الرحمة."], ["ماءً طهوراً", "تتطهّرون به من الأحداث والأوساخ."], ["أنعاماً وأناسيّ كثيراً", "حيواناً وأناساً كثيرين."], ["ولقد صرّفناه بينهم", "المطر، ينزل بأرض قوم ولا ينزل بأخرى لحكم عالية."], ["ليذّكّروا", "فيذكروا فضل الله عليهم فيشكروا ويوحّدوا."], ["فأبى أكثر الناس إلا كفوراً", "جحوداً للنعمة."]], "m": "هذا شروع في ذكر مجموعة من أدلة التوحيد، وهي مظاهر لربوبية الله المقتضية لألوهيته. أولاً الظل: مدّه الخالق وبسطه من وقت الإسفار، ثم تطلع الشمس فيأخذ في الانكماش شيئاً فشيئاً حتى تقف في كبد السماء، ثم يفيء ويطول تدريجياً لتُعرف به ساعات النهار وأوقات الصلوات، ثم يُقبض قبضاً خفياً سريعاً حين تغرب الشمس، ولو شاء لجعله ساكناً لا يبارح. ثانياً الليل والنهار: جعل الليل ساتراً كاللباس، والنوم قطعاً للعمل تحصل به راحة الأبدان، والنهار حياة بعد وفاة النوم ينتشر فيه الناس لطلب الرزق. ثالثاً إرسال الرياح مبشّرات بالمطر الذي هو الرحمة. رابعاً إنزال الماء الطهور ليحيي به الأرض الميتة ويسقيه الأنعام والأناسيّ الكثيرين. خامساً تصريف المطر بين الناس، يُمطر إقليم ويُحرم آخر حسب الحكمة الإلهية، ليذكروا فيشكروا، فأبى أكثر الناس إلا كفوراً وجحوداً، وهو أمر يقتضي التعجّب.", "h": ["عرض الأدلة الحسية على وجوب عبادة الله تعالى وتوحيده فيها، ووجوب الإيمان بالبعث والجزاء.", "بيان فائدة الظل، إذ به تُعرف ساعات النهار، وبه يُعرف وقت صلاة الظهر والعصر.", "الماء الطهور هو الباقي على أصل خلقته، فلم يخالطه شيء يغيّر طعمه أو لونه أو ريحه، وبه تُرفع الأحداث وتُغسل النجاسات."], "k": "«ثم جعلنا الشمس عليه دليلاً»… ظلٌّ يطول ويقصر يذكّرني بمواقيت صلاتي؛ فهل ألتفت إليه؟"}, {"lbl": "الآيات ٥١ – ٥٦", "q": "وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِي كُلِّ قَرۡيَةٖ نَّذِيرٗا ﴿٥١﴾ فَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا ﴿٥٢﴾ ۞وَهُوَ ٱلَّذِي مَرَجَ ٱلۡبَحۡرَيۡنِ هَٰذَا عَذۡبٞ فُرَاتٞ وَهَٰذَا مِلۡحٌ أُجَاجٞ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخٗا وَحِجۡرٗا مَّحۡجُورٗا ﴿٥٣﴾ وَهُوَ ٱلَّذِي خَلَقَ مِنَ ٱلۡمَآءِ بَشَرٗا فَجَعَلَهُۥ نَسَبٗا وَصِهۡرٗاۗ وَكَانَ رَبُّكَ قَدِيرٗا ﴿٥٤﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرٗا ﴿٥٥﴾ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا ﴿٥٦﴾", "w": [["ولو شئنا لبعثنا في كل قرية نذيراً", "رسولاً ينذر أهلها، ولكن جعلناك رسول القرى كلها."], ["وجاهدهم به", "بالقرآن، وكله حجج وبيّنات."], ["مرج البحرين", "أرسلهما متجاورين: الملح والعذب."], ["وجعل بينهما برزخاً", "حاجزاً بين الملح منهما والعذب."], ["وحجراً محجوراً", "سدّاً مانعاً، فلا يحلو الملح ولا يملح العذب."], ["خلق من الماء بشراً", "خلق الإنسان من النطفة."], ["فجعله نسباً وصهراً", "ذكوراً يُنسب إليهم، وإناثاً يُصاهر بهن."], ["ما لا ينفعهم ولا يضرّهم", "أصناماً لا تنفع ولا تضر."], ["وكان الكافر على ربه ظهيراً", "معيناً للشيطان على معصية الرحمن."]], "m": "ولو شئنا لبعثنا في كل مدينة رسولاً ينذر أهلها، ولكنا لم نشأ لحكمة، وهي أن تكون أيها الرسول أفضل الرسل وأعظمهم منزلة وثواباً، فكنت رسول القرى كلها، فاصبر وتحمّل، فلا تطع الكافرين في أي أمر أرادوه منك، وجاهدهم بالقرآن جهاداً كبيراً. ثم واصل تعالى ذكر مظاهر ربوبيته: وهو الذي أرسل البحرين الملح والعذب متجاورين، هذا عذب فرات سائغ شرابه، وهذا ملح أجاج لا يُشرب، وجعل بينهما حاجزاً مانعاً من اختلاطهما مع وجودهما في مكان واحد. وهو الذي خلق من النطفة الإنسان، فجعله ذكوراً يُنسب إليهم وإناثاً يُصاهر بهن، وكان ربك قديراً على ما يريد. هذه مظاهر الربوبية المقتضية لعبادته وحده، والمشركون يعبدون من دونه أصناماً لا تنفعهم إن عبدوها ولا تضرهم إن تركوها، فيعبدون الشيطان الذي زيّن لهم ذلك، فكان الكافر معيناً للشيطان على الرحمن. وما أرسلناك إلا مبشّراً للمؤمنين بالجنة ونذيراً للكافرين بالنار، أما هداية القلوب فإلى الله.", "h": ["الإشارة إلى الحكمة في عدم تعدّد الرسل في زمن البعثة المحمدية، والاكتفاء بالرسول ﷺ.", "حرمة طاعة الكافرين في أمور الدين والشرع.", "من الجهاد جهاد الكفار والملاحدة بالحجج القرآنية والآيات التنزيلية.", "مظاهر العلم والقدرة الإلهية في عدم اختلاط البحرين مع وجودهما في مكان واحد، وفي خلق الإنسان من ماء وجعله ذكراً وأنثى للتناسل وحفظ النوع.", "التنديد بالكافرين الذين يكونون عوناً للشيطان على الرحمن."], "k": "«وجاهدهم به جهاداً كبيراً»… القرآن نفسه هو السلاح؛ فكم آية أحملها في قلبي حجّةً للحق؟"}, {"lbl": "الآيات ٥٧ – ٦٢", "q": "قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ﴿٥٧﴾ وَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا ﴿٥٨﴾ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَٰنُ فَسۡـَٔلۡ بِهِۦ خَبِيرٗا ﴿٥٩﴾ وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا۩ ﴿٦٠﴾ تَبَارَكَ ٱلَّذِي جَعَلَ فِي ٱلسَّمَآءِ بُرُوجٗا وَجَعَلَ فِيهَا سِرَٰجٗا وَقَمَرٗا مُّنِيرٗا ﴿٦١﴾ وَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا ﴿٦٢﴾", "w": [["ما أسألكم عليه من أجر", "على البلاغ أجراً أتقاضاه منكم."], ["سبيلاً", "طريقاً يصل به إلى مرضاة ربه، وذلك بإنفاق ماله في سبيله."], ["وسبّح بحمده", "قل: سبحان الله وبحمده."], ["في ستة أيام", "من أيام الدنيا."], ["ثم استوى على العرش", "العرش سرير الملك، والاستواء معلوم، والكيف مجهول."], ["فاسأل به خبيراً", "اسأل بالرحمن خبيراً يُنبئك بعظمته."], ["وزادهم نفوراً", "زادهم القول لهم: اسجدوا للرحمن، نفوراً من الإيمان."], ["جعل في السماء بروجاً", "منازل الكواكب السيّارة، وهي اثنا عشر برجاً."], ["سراجاً", "شمساً."], ["خلفة", "يخلف أحدهما الآخر."], ["لمن أراد أن يذّكّر", "ما فاته في أحدهما فيفعله في الآخر."], ["أو أراد شكوراً", "شكراً لنعم ربه بالصيام والصلاة فيهما."]], "m": "بعد هذا العرض العظيم لمظاهر الربوبية أمر الله رسوله أن يقول للمشركين: ما أسألكم على هذا البيان أجراً، لكن من شاء أن ينفق من ماله في وجوه البر يتقرّب به إلى ربه فله ذلك، ليتخذ به طريقاً إلى رضاه. وأمره أن يمضي في دعوته متوكلاً على الحي الذي لا يموت، وغيره يموت، وأن يستعين على صبره بالتسبيح، وهو أمر بالذكر والصلاة وسائر العبادات فإنها العون الكبير على الثبات، وكفى بالله بذنوب عباده خبيراً فلا تحزن عليهم. ثم أثنى تعالى على نفسه: الذي خلق السماوات والأرض وما بينهما في ستة أيام، ثم استوى على العرش استواءً يليق بجلاله، الرحمن الذي عمّت رحمته العالمين، فاسأل به خبيراً بخلقه. وإذا قال لهم الرسول: اسجدوا للرحمن، قالوا متجاهلين: وما الرحمن؟ أنسجد لما تأمرنا؟ وزادهم ذلك نفوراً. تبارك الذي جعل في السماء بروجاً هي منازل الكواكب، وجعل فيها شمساً سراجاً وقمراً منيراً، وهو الذي جعل الليل والنهار يخلف أحدهما الآخر، فمن نسي عملاً بالنهار ذكره بالليل فعمله، ومن أراد أن يشكر فالليل للتهجّد والقيام والنهار للصيام والجهاد.", "h": ["الداعي إلى الله ينبغي ألا يأخذ أجراً ممن يدعوهم إلى الله تعالى، ومن أراد أن يتطوّع من نفسه فينفق في سبيل الله فذلك له.", "وجوب التوكّل على الله، فإنه الحي الذي لا يموت وغيره يموت.", "وجوب التسبيح والذكر والعبادة، وهذه هي زاد العبد وعدّته وعونه.", "مشروعية السجود عند قوله تعالى: «وزادهم نفوراً» للقارئ والمستمع.", "صفة استواء الرحمن على عرشه، فيجب الإيمان بها على ما يليق بجلال الله وكماله.", "الترغيب في الذكر والشكر، واغتنام الفرص للعبادة والطاعة."], "k": "«لمن أراد أن يذّكّر أو أراد شكوراً»… ما فاتني نهاراً لم يفت؛ فهل أجعل ليلتي فرصة للتدارك؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (259, 25, 63, 77, 'سورة الفرقان ٦٣ – ٧٧', '«وعباد الرحمن الذين يمشون على الأرض هوناً»: صفات عباد الرحمن، و«قل ما يعبأ بكم ربي لولا دعاؤكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 259) = $j$[{"lbl": "الآيات ٦٣ – ٧١", "q": "وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا ﴿٦٣﴾ وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا ﴿٦٤﴾ وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ﴿٦٥﴾ إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ﴿٦٦﴾ وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا ﴿٦٧﴾ وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا ﴿٦٨﴾ يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ مُهَانًا ﴿٦٩﴾ إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿٧٠﴾ وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابٗا ﴿٧١﴾", "w": [["يمشون على الأرض هوناً", "في سكينة ووقار."], ["وإذا خاطبهم الجاهلون", "بما يكرهون من الأقوال."], ["قالوا سلاماً", "قولاً يسلمون به من الإثم."], ["سجّداً وقياماً", "يصلّون بالليل."], ["إن عذابها كان غراماً", "لازماً لا يفارق صاحبه."], ["ساءت مستقراً ومقاماً", "بئست موضع إقامة واستقرار."], ["لم يسرفوا ولم يقتروا", "لم يبذّروا ولم يضيّقوا."], ["وكان بين ذلك قواماً", "وسطاً بين الإسراف والتقتير."], ["إلا بالحق", "وهو واحد من ثلاث: كفر بعد إيمان، أو زنى بعد إحصان، أو قتل ظلماً وعدواناً."], ["يلق أثاماً", "عقوبة شديدة."], ["يبدّل الله سيئاتهم حسنات", "يمحو بالتوبة سوابق معاصيهم، ويُثبت مكانها لواحق طاعاتهم."]], "m": "لما أنكر المشركون الرحمن وقالوا: وما الرحمن؟ ناسب أن يذكر لهم صفات عباد الرحمن ليعرفوا الرحمن بعباده، فوصفهم بثماني صفات. الأولى: يمشون على الأرض متواضعين عليهم السكينة والوقار، ليسوا جبابرة متكبرين، وإذا خاطبهم السفهاء بما يكرهون قالوا قولاً يسلمون به من الإثم، فلا يردّون السيئة بالسيئة. الثانية: يقضون ليلهم بين السجود والقيام. الثالثة: يقولون: ربنا اصرف عنا عذاب جهنم، لقوة يقينهم كأنهم يشعرون بلهبها يدنو من وجوههم، إن عذابها كان لازماً لا يفارق صاحبه، إنها بئست موضع إقامة واستقرار. الرابعة: إذا أنفقوا لم يتجاوزوا الحد ولم يقصّروا في الواجب، وكان إنفاقهم عدلاً بين ذلك. الخامسة: لا يدعون مع الله إلهاً آخر، ولا يقتلون النفس التي حرّم الله إلا بالحق، ولا يزنون. ومن يفعل ذلك يلق عقوبة شديدة، يُضاعف له العذاب ويخلد فيه مهاناً، إلا من تاب وآمن وعمل صالحاً فأولئك يبدّل الله سيئاتهم حسنات، يمحوها بتوبتهم ويكتب مكانها طاعاتهم، ومن تاب وعمل صالحاً فإنه يرجع إلى الله مرجعاً مرضياً.", "h": ["بيان صفات عباد الرحمن الذين بهم يُعرف الرحمن عز وجل.", "فضيلة التواضع والسكينة في المشي والوقار.", "فضيلة ردّ السيئة بالحسنة، والقول السليم من الإثم.", "فضيلة قيام الليل والخوف من عذاب النار.", "فضيلة الاعتدال والقصد في النفقة، وهي الحسنة بين السيئتين.", "حرمة الشرك وقتل النفس والزنى، وأنها أمهات الكبائر.", "التوبة تجبّ ما قبلها، والندب إلى التوبة، وأنها مقبولة ما لم يُغرغر."], "k": "«وإذا خاطبهم الجاهلون قالوا سلاماً»… آخر مرة استُفززت فيها، هل خرجت سالماً من الإثم؟"}, {"lbl": "الآيات ٧٢ – ٧٧", "q": "وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا ﴿٧٢﴾ وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا ﴿٧٣﴾ وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا ﴿٧٤﴾ أُوْلَـٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا ﴿٧٥﴾ خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ﴿٧٦﴾ قُلۡ مَا يَعۡبَؤُاْ بِكُمۡ رَبِّي لَوۡلَا دُعَآؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ يَكُونُ لِزَامَۢا ﴿٧٧﴾", "w": [["لا يشهدون الزور", "لا يحضرون مجالسه، ولا يشهدون بالكذب والباطل."], ["وإذا مرّوا باللغو", "بالكلام السيئ القبيح وكل ما لا خير فيه."], ["مرّوا كراماً", "معرضين عنه، مكرمين أنفسهم عن سماعه أو المشاركة فيه."], ["وإذا ذُكّروا بآيات ربهم", "إذا وُعظوا بآيات القرآن."], ["لم يخرّوا عليها صمّاً وعمياناً", "بل يُصغون فيسمعون ويعون ما تدعو إليه، ويبصرون ما تعرضه."], ["قرّة أعين", "ما تقرّ به أعيننا، وهو أن نراهم مطيعين لك."], ["واجعلنا للمتقين إماماً", "قدوة يقتدون بنا في الخير."], ["يُجزون الغرفة", "الدرجة العليا في الجنة."], ["بما صبروا", "على طاعتك بامتثال الأمر واجتناب النهي."], ["ما يعبأ بكم ربي", "ما يكترث بكم ولا يبالي."], ["لولا دعاؤكم", "إياه، أي عبادتكم له."], ["فسوف يكون لزاماً", "العذاب لازماً لكم في بدر ويوم القيامة."]], "m": "ما زال السياق في صفات عباد الرحمن. السادسة: لا يحضرون مجالس الزور، وهو الباطل والكذب، ولا يقولونه ولا يشهدون به، وإذا مرّوا باللغو، وهو كل قول وعمل لا خير فيه، مرّوا مكرمين أنفسهم من التلوّث به. السابعة: إذا ذكّرهم أحد بآيات ربهم لم يحنوا رؤوسهم عليها صمّاً لا يسمعون مواعظها ولا عمياناً لا يشاهدون آثارها، بل يسمعونها واعين لما تدعو إليه، متأثّرين بها. الثامنة: يقولون في دعائهم: ربنا أعطنا من أزواجنا وذرّياتنا ما تقرّ به أعيننا، بأن نراهم يتعلّمون الهدى ويعملون به، واجعلنا قدوة صالحة يقتدي بنا المتقون في الخير. أولئك يُجزون الدرجة العليا في الجنة بما صبروا على طاعة مولاهم وما يلحقهم من أذى في ذاته، وتتلقّاهم الملائكة فيها بالتحية والسلام، خالدين فيها، حسنت مستقراً ومقاماً. ثم قال تعالى لرسوله: قل للمشركين: ما يكترث بكم ربي ولا يبالي لولا عبادة من يعبده منكم، أما وقد كذّبتم فسوف يكون العذاب لازماً لكم، وقد ذاقوه يوم بدر، ويلازمهم إلى مستقرّهم في جهنم.", "h": ["حرمة شهود مجالس الزور، وحرمة شهادة الزور.", "فضيلة الإعراض عن اللغو، فعلاً كان أو قولاً.", "فضيلة تدبّر القرآن وحسن الاستماع لتلاوته، والاتعاظ بمواعظه والعمل بهدايته.", "فضيلة علوّ الهمة وسموّ الروح، وطلب الكمال والقدوة في الخير.", "لا قيمة للإنسان، وهو أشرف الحيوانات، لولا عبادته الله عز وجل."], "k": "«لم يخرّوا عليها صمّاً وعمياناً»… حين أقرأ هذه الآيات الآن، هل أسمع فعلاً أم أمرّ عليها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 259;
insert into public.tdb_cards(topic, i, body) select 259, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٣ – ٧١", "q": "وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا ﴿٦٣﴾ وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا ﴿٦٤﴾ وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ﴿٦٥﴾ إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ﴿٦٦﴾ وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا ﴿٦٧﴾ وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا ﴿٦٨﴾ يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ مُهَانًا ﴿٦٩﴾ إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿٧٠﴾ وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابٗا ﴿٧١﴾", "w": [["يمشون على الأرض هوناً", "في سكينة ووقار."], ["وإذا خاطبهم الجاهلون", "بما يكرهون من الأقوال."], ["قالوا سلاماً", "قولاً يسلمون به من الإثم."], ["سجّداً وقياماً", "يصلّون بالليل."], ["إن عذابها كان غراماً", "لازماً لا يفارق صاحبه."], ["ساءت مستقراً ومقاماً", "بئست موضع إقامة واستقرار."], ["لم يسرفوا ولم يقتروا", "لم يبذّروا ولم يضيّقوا."], ["وكان بين ذلك قواماً", "وسطاً بين الإسراف والتقتير."], ["إلا بالحق", "وهو واحد من ثلاث: كفر بعد إيمان، أو زنى بعد إحصان، أو قتل ظلماً وعدواناً."], ["يلق أثاماً", "عقوبة شديدة."], ["يبدّل الله سيئاتهم حسنات", "يمحو بالتوبة سوابق معاصيهم، ويُثبت مكانها لواحق طاعاتهم."]], "m": "لما أنكر المشركون الرحمن وقالوا: وما الرحمن؟ ناسب أن يذكر لهم صفات عباد الرحمن ليعرفوا الرحمن بعباده، فوصفهم بثماني صفات. الأولى: يمشون على الأرض متواضعين عليهم السكينة والوقار، ليسوا جبابرة متكبرين، وإذا خاطبهم السفهاء بما يكرهون قالوا قولاً يسلمون به من الإثم، فلا يردّون السيئة بالسيئة. الثانية: يقضون ليلهم بين السجود والقيام. الثالثة: يقولون: ربنا اصرف عنا عذاب جهنم، لقوة يقينهم كأنهم يشعرون بلهبها يدنو من وجوههم، إن عذابها كان لازماً لا يفارق صاحبه، إنها بئست موضع إقامة واستقرار. الرابعة: إذا أنفقوا لم يتجاوزوا الحد ولم يقصّروا في الواجب، وكان إنفاقهم عدلاً بين ذلك. الخامسة: لا يدعون مع الله إلهاً آخر، ولا يقتلون النفس التي حرّم الله إلا بالحق، ولا يزنون. ومن يفعل ذلك يلق عقوبة شديدة، يُضاعف له العذاب ويخلد فيه مهاناً، إلا من تاب وآمن وعمل صالحاً فأولئك يبدّل الله سيئاتهم حسنات، يمحوها بتوبتهم ويكتب مكانها طاعاتهم، ومن تاب وعمل صالحاً فإنه يرجع إلى الله مرجعاً مرضياً.", "h": ["بيان صفات عباد الرحمن الذين بهم يُعرف الرحمن عز وجل.", "فضيلة التواضع والسكينة في المشي والوقار.", "فضيلة ردّ السيئة بالحسنة، والقول السليم من الإثم.", "فضيلة قيام الليل والخوف من عذاب النار.", "فضيلة الاعتدال والقصد في النفقة، وهي الحسنة بين السيئتين.", "حرمة الشرك وقتل النفس والزنى، وأنها أمهات الكبائر.", "التوبة تجبّ ما قبلها، والندب إلى التوبة، وأنها مقبولة ما لم يُغرغر."], "k": "«وإذا خاطبهم الجاهلون قالوا سلاماً»… آخر مرة استُفززت فيها، هل خرجت سالماً من الإثم؟"}, {"lbl": "الآيات ٧٢ – ٧٧", "q": "وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا ﴿٧٢﴾ وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا ﴿٧٣﴾ وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا ﴿٧٤﴾ أُوْلَـٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا ﴿٧٥﴾ خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ﴿٧٦﴾ قُلۡ مَا يَعۡبَؤُاْ بِكُمۡ رَبِّي لَوۡلَا دُعَآؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ يَكُونُ لِزَامَۢا ﴿٧٧﴾", "w": [["لا يشهدون الزور", "لا يحضرون مجالسه، ولا يشهدون بالكذب والباطل."], ["وإذا مرّوا باللغو", "بالكلام السيئ القبيح وكل ما لا خير فيه."], ["مرّوا كراماً", "معرضين عنه، مكرمين أنفسهم عن سماعه أو المشاركة فيه."], ["وإذا ذُكّروا بآيات ربهم", "إذا وُعظوا بآيات القرآن."], ["لم يخرّوا عليها صمّاً وعمياناً", "بل يُصغون فيسمعون ويعون ما تدعو إليه، ويبصرون ما تعرضه."], ["قرّة أعين", "ما تقرّ به أعيننا، وهو أن نراهم مطيعين لك."], ["واجعلنا للمتقين إماماً", "قدوة يقتدون بنا في الخير."], ["يُجزون الغرفة", "الدرجة العليا في الجنة."], ["بما صبروا", "على طاعتك بامتثال الأمر واجتناب النهي."], ["ما يعبأ بكم ربي", "ما يكترث بكم ولا يبالي."], ["لولا دعاؤكم", "إياه، أي عبادتكم له."], ["فسوف يكون لزاماً", "العذاب لازماً لكم في بدر ويوم القيامة."]], "m": "ما زال السياق في صفات عباد الرحمن. السادسة: لا يحضرون مجالس الزور، وهو الباطل والكذب، ولا يقولونه ولا يشهدون به، وإذا مرّوا باللغو، وهو كل قول وعمل لا خير فيه، مرّوا مكرمين أنفسهم من التلوّث به. السابعة: إذا ذكّرهم أحد بآيات ربهم لم يحنوا رؤوسهم عليها صمّاً لا يسمعون مواعظها ولا عمياناً لا يشاهدون آثارها، بل يسمعونها واعين لما تدعو إليه، متأثّرين بها. الثامنة: يقولون في دعائهم: ربنا أعطنا من أزواجنا وذرّياتنا ما تقرّ به أعيننا، بأن نراهم يتعلّمون الهدى ويعملون به، واجعلنا قدوة صالحة يقتدي بنا المتقون في الخير. أولئك يُجزون الدرجة العليا في الجنة بما صبروا على طاعة مولاهم وما يلحقهم من أذى في ذاته، وتتلقّاهم الملائكة فيها بالتحية والسلام، خالدين فيها، حسنت مستقراً ومقاماً. ثم قال تعالى لرسوله: قل للمشركين: ما يكترث بكم ربي ولا يبالي لولا عبادة من يعبده منكم، أما وقد كذّبتم فسوف يكون العذاب لازماً لكم، وقد ذاقوه يوم بدر، ويلازمهم إلى مستقرّهم في جهنم.", "h": ["حرمة شهود مجالس الزور، وحرمة شهادة الزور.", "فضيلة الإعراض عن اللغو، فعلاً كان أو قولاً.", "فضيلة تدبّر القرآن وحسن الاستماع لتلاوته، والاتعاظ بمواعظه والعمل بهدايته.", "فضيلة علوّ الهمة وسموّ الروح، وطلب الكمال والقدوة في الخير.", "لا قيمة للإنسان، وهو أشرف الحيوانات، لولا عبادته الله عز وجل."], "k": "«لم يخرّوا عليها صمّاً وعمياناً»… حين أقرأ هذه الآيات الآن، هل أسمع فعلاً أم أمرّ عليها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (260, 26, 1, 31, 'سورة الشعراء ١ – ٣١', '«لعلك باخع نفسك ألا يكونوا مؤمنين»، وتكليف موسى ﵇ وجداله مع فرعون: «قال وما رب العالمين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 260) = $j$[{"lbl": "الآيات ١ – ٩", "q": "طسٓمٓ ﴿١﴾ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ أَلَّا يَكُونُواْ مُؤۡمِنِينَ ﴿٣﴾ إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةٗ فَظَلَّتۡ أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ ﴿٤﴾ وَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ ﴿٥﴾ فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٦﴾ أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ ﴿٧﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿٨﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٩﴾", "w": [["طسم", "الله أعلم بمراده بذلك."], ["الكتاب المبين", "القرآن المبيّن للحق من الباطل."], ["باخع نفسك", "قاتلها من الغم."], ["ألا يكونوا مؤمنين", "من أجل عدم إيمانهم بك."], ["آية", "نخوّفهم بها."], ["من ذكر", "من قرآن."], ["معرضين", "غير ملتفتين إليه."], ["زوج كريم", "صنف حسن."], ["العزيز", "الغالب على أمره ومراده."], ["الرحيم", "بالمؤمنين من عباده."]], "m": "طسم، تُقرأ: طا سين ميم، والله أعلم بمراده منها، وفيها إشارة إلى أن القرآن مؤلّف من مثل هذه الحروف، وعجز العرب عن الإتيان بسورة من مثله دليل قاطع على أنه كلام الله. تلك آيات القرآن المبيّن للحق من الباطل والهدى من الضلال. لعلك قاتل نفسك غمّاً إن لم يؤمن قومك، فأشفق على نفسك، فليس عليك هدايتهم وإنما عليك البلاغ. ولو أردنا هدايتهم قسراً لأنزلنا عليهم من السماء آية فتظل أعناقهم خاضعة لها تتوقّع نزولها فتهلكهم، فيؤمنوا إيمان إكراه لا ينفع صاحبه ولا يزكّي نفسه. وما يأتيهم من قرآن يُنزّله الرحمن إلا أعرضوا عنه، فقد كذّبوا به، فسيأتيهم خبر العذاب الذي كانوا به يستهزئون. أوَلم ينظروا إلى الأرض الميتة ينزل الله عليها الماء فتحيا وينبت فيها من كل صنف حسن من النبات؟ إن في ذلك لآية على البعث، وما كان أكثرهم مؤمنين، وإن ربك لهو الغالب المنتقم من أعدائه، الرحيم بأوليائه.", "h": ["بيان أن القرآن الكريم معجز، لأنه مؤلّف من مثل طا سين ميم.", "بيان ما كان الرسول ﷺ يناله من الغم والحزن وتكذيب قومه له.", "بيان أن إيمان المكره لا ينفعه.", "التحذير من عاقبة التكذيب بآيات الله وعدم الاكتراث بها.", "في إحياء الأرض بالماء وإنبات النباتات المختلفة فيها دليل على البعث الآخر."], "k": "«لعلك باخع نفسك»… حرص النبي ﷺ على هداية الناس كاد يُهلكه؛ فكم يشغلني حال من حولي؟"}, {"lbl": "الآيات ١٠ – ١٧", "q": "وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٠﴾ قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ ﴿١١﴾ قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ﴿١٢﴾ وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ﴿١٣﴾ وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ﴿١٤﴾ قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ ﴿١٥﴾ فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٦﴾ أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٧﴾", "w": [["وإذ نادى ربك", "اذكر لقومك إذ نادى ربك موسى."], ["أن ائت", "بأن ائت القوم الظالمين."], ["ألا يتقون", "ألا يخافون الله ربهم ورب آبائهم الأولين؟"], ["ويضيق صدري", "من تكذيبهم لي."], ["ولا ينطلق لساني", "للعقدة التي به."], ["فأرسل إلى هارون", "إلى أخي هارون ليكون معي في إبلاغ رسالتي."], ["ولهم عليّ ذنب", "ذنب القبطي الذي قتله موسى قبل خروجه إلى مدين."], ["قال كلا", "لا يقتلونك."], ["فاذهبا", "أنت وهارون."], ["إنا رسول رب العالمين", "إليك."]], "m": "هذا بداية سلسلة من القصص، بدأت بموسى ﵇ وخُتمت بشعيب ﵇، ليشاهد المشركون أحداثها ويعرفوا نتائجها، وهي دمار المكذّبين مهما كانت قوتهم. واذكر إذ نادى ربك موسى في الوادي المبارك: أن ائت القوم الظالمين، قوم فرعون، الذين ظلموا أنفسهم بالكفر وظلموا بني إسرائيل بتعذيبهم، فقل لهم: ألا تتقون ربكم؟ قال موسى: رب إني أخاف أن يكذّبون، ويضيق صدري لذلك، ولا ينطلق لساني للعقدة التي به، فأرسل جبريل إلى هارون ليكون معيناً لي، ولهم عليّ ذنب، قتل القبطي، فأخاف أن يقتلون. قال تعالى: كلا لن يقتلوك، فاذهبا بآياتنا، العصا واليد، إنا معكم مستمعون لما تقولان وما يُقال لكما، فأتيا فرعون فقولا: إنا رسول رب العالمين إليك، أن أرسل معنا بني إسرائيل لنخرج بهم إلى أرض الشام.", "h": ["إثبات صفة الكلام لله تعالى بندائه موسى ﵇.", "لا بأس بإبداء التخوّف عند الإقدام على الأمر الصعب، ولا يقدح ذلك في الإيمان.", "مشروعية طلب العون والمساعدة من المسؤولين إذا كلّفوا المرء بما يصعب."], "k": "«فأرسل إلى هارون»… موسى ﵇ لم يستحِ أن يطلب معيناً؛ فلِمَ أحمل وحدي ما يصعب عليّ؟"}, {"lbl": "الآيات ١٨ – ٢٢", "q": "قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ ﴿١٨﴾ وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ ﴿١٩﴾ قَالَ فَعَلۡتُهَآ إِذٗا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ ﴿٢٠﴾ فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِي رَبِّي حُكۡمٗا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ ﴿٢١﴾ وَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٢٢﴾", "w": [["ألم نربّك فينا وليداً", "في منازلنا صغيراً قريباً من أيام الولادة."], ["ولبثت فينا من عمرك سنين", "أقمت بيننا قرابة ثلاثين سنة."], ["وفعلت فعلتك التي فعلت", "قتلت الرجل القبطي."], ["وأنت من الكافرين", "الجاحدين لنعمتي عليك بالتربية."], ["وأنا من الضالين", "إذ لم يكن عندي يومئذ من علم ربي ورسالته ما عندي الآن."], ["أن عبّدت بني إسرائيل", "هل تعبيدك لبني إسرائيل يُعدّ نعمة تمنّ بها عليّ؟"]], "m": "ردّ فرعون على موسى ﵇ ممتنّاً عليه: ألم نربّك فينا صغيراً، ولبثت في قصرنا سنين من عمرك، وفعلت فعلتك الشنعاء، قتل القبطي، وأنت من الجاحدين لنعمنا عليك؟ فردّ موسى: فعلتها يومئذ وأنا من الجاهلين، إذ لم يكن ربي قد علّمني ما علّمني الآن ولا أرسلني، ففررت منكم لما خفتكم بسبب ذلك القتل، فوهب لي ربي علماً نافعاً وجعلني من المرسلين. ثم ردّ على امتنان فرعون بتربيته: أوتلك نعمة تمنّها عليّ، وهي أنك استعبدت بني إسرائيل تستعملهم كما تشاء، ولم تستعبدني لاتخاذك إياي ولداً؟ فأين النعمة؟", "h": ["قبح جريمة القتل عند كافة الناس مؤمنهم وكافرهم، وهو أمر فطري.", "جواز التذكير بالإحسان لمن أنكره، ولكن لا على سبيل الامتنان، فإنه محبط للعمل.", "جواز إطلاق لفظ الضلال على الجهل، كما قال موسى: «وأنا من الضالين» أي الجاهلين قبل أن يعلّمني ربي.", "مشروعية الفرار من الخوف إذا لم يكن في البلد قضاء عادل، وإلا لما جاز الهرب من وجه العدالة."], "k": "«فعلتها إذاً وأنا من الضالين»… اعترف موسى ﵇ بخطئه القديم دون مراوغة؛ فهل أملك هذه الشجاعة؟"}, {"lbl": "الآيات ٢٣ – ٣١", "q": "قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ ﴿٢٣﴾ قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ ﴿٢٤﴾ قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ ﴿٢٥﴾ قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ﴿٢٦﴾ قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ ﴿٢٧﴾ قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ﴿٢٨﴾ قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ ﴿٢٩﴾ قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ ﴿٣٠﴾ قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٣١﴾", "w": [["وما رب العالمين", "الذي تقول إنك رسوله، من أي جنس هو؟"], ["رب السماوات والأرض وما بينهما", "خالق ذلك كله ومالكه."], ["إن كنتم موقنين", "بأن كل مخلوق لا بد له من خالق."], ["لمن حوله", "من أشراف قومه ورجال دولته."], ["ألا تستمعون", "جوابه الذي لم يطابق السؤال في نظره."], ["أوَلو جئتك بشيء مبين", "أتسجنني ولو جئتك ببرهان وحجة على رسالتي؟"], ["فأت به إن كنت من الصادقين", "فيما تدّعي."]], "m": "لما قال موسى: إني رسول رب العالمين، قال فرعون في عناد ومكابرة: وما رب العالمين؟ أي من أي جنس هو؟ فأجابه موسى: رب السماوات والأرض وما بينهما، خالق ذلك كله ومالكه، إن كنتم موقنين بأن كل مخلوق لا بد له من خالق. فقال فرعون في استخفاف لمن حوله: ألا تستمعون؟ كأنما قال موسى أمراً عجباً. فقال موسى: ربكم ورب آبائكم الأولين. فاغتاظ فرعون وقال: إن رسولكم الذي أُرسل إليكم لمجنون. فردّ موسى: رب المشرق والمغرب وما بينهما، رب الكون كله، إن كنتم تعقلون. فقال فرعون: لئن اتخذت إلهاً غيري لأجعلنّك من المسجونين. فقال موسى: أتسجنني ولو جئتك ببرهان ساطع على صدقي؟ قال فرعون: فأت به إن كنت من الصادقين.", "h": ["تقرير الربوبية المقتضية للألوهية من طريق هذا الحوار، ليسمع ذلك المشركون ويعلموا أنهم مسبوقون بالشرك والكفر وأنهم ضالّون.", "سنة أهل الباطل أنهم يفجرون في الخصومة، وفي الحديث: «وإذا خاصم فجر».", "أهل الكبر والعلوّ في الأرض إذا أعيتهم الحجج لجأوا إلى التهديد والوعيد."], "k": "«لأجعلنّك من المسجونين»… حين تنفد الحجة يبدأ التهديد؛ فهل أرفع صوتي حين أعجز عن الإقناع؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 260;
insert into public.tdb_cards(topic, i, body) select 260, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٩", "q": "طسٓمٓ ﴿١﴾ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ أَلَّا يَكُونُواْ مُؤۡمِنِينَ ﴿٣﴾ إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةٗ فَظَلَّتۡ أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ ﴿٤﴾ وَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ ﴿٥﴾ فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٦﴾ أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ ﴿٧﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿٨﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٩﴾", "w": [["طسم", "الله أعلم بمراده بذلك."], ["الكتاب المبين", "القرآن المبيّن للحق من الباطل."], ["باخع نفسك", "قاتلها من الغم."], ["ألا يكونوا مؤمنين", "من أجل عدم إيمانهم بك."], ["آية", "نخوّفهم بها."], ["من ذكر", "من قرآن."], ["معرضين", "غير ملتفتين إليه."], ["زوج كريم", "صنف حسن."], ["العزيز", "الغالب على أمره ومراده."], ["الرحيم", "بالمؤمنين من عباده."]], "m": "طسم، تُقرأ: طا سين ميم، والله أعلم بمراده منها، وفيها إشارة إلى أن القرآن مؤلّف من مثل هذه الحروف، وعجز العرب عن الإتيان بسورة من مثله دليل قاطع على أنه كلام الله. تلك آيات القرآن المبيّن للحق من الباطل والهدى من الضلال. لعلك قاتل نفسك غمّاً إن لم يؤمن قومك، فأشفق على نفسك، فليس عليك هدايتهم وإنما عليك البلاغ. ولو أردنا هدايتهم قسراً لأنزلنا عليهم من السماء آية فتظل أعناقهم خاضعة لها تتوقّع نزولها فتهلكهم، فيؤمنوا إيمان إكراه لا ينفع صاحبه ولا يزكّي نفسه. وما يأتيهم من قرآن يُنزّله الرحمن إلا أعرضوا عنه، فقد كذّبوا به، فسيأتيهم خبر العذاب الذي كانوا به يستهزئون. أوَلم ينظروا إلى الأرض الميتة ينزل الله عليها الماء فتحيا وينبت فيها من كل صنف حسن من النبات؟ إن في ذلك لآية على البعث، وما كان أكثرهم مؤمنين، وإن ربك لهو الغالب المنتقم من أعدائه، الرحيم بأوليائه.", "h": ["بيان أن القرآن الكريم معجز، لأنه مؤلّف من مثل طا سين ميم.", "بيان ما كان الرسول ﷺ يناله من الغم والحزن وتكذيب قومه له.", "بيان أن إيمان المكره لا ينفعه.", "التحذير من عاقبة التكذيب بآيات الله وعدم الاكتراث بها.", "في إحياء الأرض بالماء وإنبات النباتات المختلفة فيها دليل على البعث الآخر."], "k": "«لعلك باخع نفسك»… حرص النبي ﷺ على هداية الناس كاد يُهلكه؛ فكم يشغلني حال من حولي؟"}, {"lbl": "الآيات ١٠ – ١٧", "q": "وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٠﴾ قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ ﴿١١﴾ قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ﴿١٢﴾ وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ﴿١٣﴾ وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ﴿١٤﴾ قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ ﴿١٥﴾ فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٦﴾ أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٧﴾", "w": [["وإذ نادى ربك", "اذكر لقومك إذ نادى ربك موسى."], ["أن ائت", "بأن ائت القوم الظالمين."], ["ألا يتقون", "ألا يخافون الله ربهم ورب آبائهم الأولين؟"], ["ويضيق صدري", "من تكذيبهم لي."], ["ولا ينطلق لساني", "للعقدة التي به."], ["فأرسل إلى هارون", "إلى أخي هارون ليكون معي في إبلاغ رسالتي."], ["ولهم عليّ ذنب", "ذنب القبطي الذي قتله موسى قبل خروجه إلى مدين."], ["قال كلا", "لا يقتلونك."], ["فاذهبا", "أنت وهارون."], ["إنا رسول رب العالمين", "إليك."]], "m": "هذا بداية سلسلة من القصص، بدأت بموسى ﵇ وخُتمت بشعيب ﵇، ليشاهد المشركون أحداثها ويعرفوا نتائجها، وهي دمار المكذّبين مهما كانت قوتهم. واذكر إذ نادى ربك موسى في الوادي المبارك: أن ائت القوم الظالمين، قوم فرعون، الذين ظلموا أنفسهم بالكفر وظلموا بني إسرائيل بتعذيبهم، فقل لهم: ألا تتقون ربكم؟ قال موسى: رب إني أخاف أن يكذّبون، ويضيق صدري لذلك، ولا ينطلق لساني للعقدة التي به، فأرسل جبريل إلى هارون ليكون معيناً لي، ولهم عليّ ذنب، قتل القبطي، فأخاف أن يقتلون. قال تعالى: كلا لن يقتلوك، فاذهبا بآياتنا، العصا واليد، إنا معكم مستمعون لما تقولان وما يُقال لكما، فأتيا فرعون فقولا: إنا رسول رب العالمين إليك، أن أرسل معنا بني إسرائيل لنخرج بهم إلى أرض الشام.", "h": ["إثبات صفة الكلام لله تعالى بندائه موسى ﵇.", "لا بأس بإبداء التخوّف عند الإقدام على الأمر الصعب، ولا يقدح ذلك في الإيمان.", "مشروعية طلب العون والمساعدة من المسؤولين إذا كلّفوا المرء بما يصعب."], "k": "«فأرسل إلى هارون»… موسى ﵇ لم يستحِ أن يطلب معيناً؛ فلِمَ أحمل وحدي ما يصعب عليّ؟"}, {"lbl": "الآيات ١٨ – ٢٢", "q": "قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ ﴿١٨﴾ وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ ﴿١٩﴾ قَالَ فَعَلۡتُهَآ إِذٗا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ ﴿٢٠﴾ فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِي رَبِّي حُكۡمٗا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ ﴿٢١﴾ وَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٢٢﴾", "w": [["ألم نربّك فينا وليداً", "في منازلنا صغيراً قريباً من أيام الولادة."], ["ولبثت فينا من عمرك سنين", "أقمت بيننا قرابة ثلاثين سنة."], ["وفعلت فعلتك التي فعلت", "قتلت الرجل القبطي."], ["وأنت من الكافرين", "الجاحدين لنعمتي عليك بالتربية."], ["وأنا من الضالين", "إذ لم يكن عندي يومئذ من علم ربي ورسالته ما عندي الآن."], ["أن عبّدت بني إسرائيل", "هل تعبيدك لبني إسرائيل يُعدّ نعمة تمنّ بها عليّ؟"]], "m": "ردّ فرعون على موسى ﵇ ممتنّاً عليه: ألم نربّك فينا صغيراً، ولبثت في قصرنا سنين من عمرك، وفعلت فعلتك الشنعاء، قتل القبطي، وأنت من الجاحدين لنعمنا عليك؟ فردّ موسى: فعلتها يومئذ وأنا من الجاهلين، إذ لم يكن ربي قد علّمني ما علّمني الآن ولا أرسلني، ففررت منكم لما خفتكم بسبب ذلك القتل، فوهب لي ربي علماً نافعاً وجعلني من المرسلين. ثم ردّ على امتنان فرعون بتربيته: أوتلك نعمة تمنّها عليّ، وهي أنك استعبدت بني إسرائيل تستعملهم كما تشاء، ولم تستعبدني لاتخاذك إياي ولداً؟ فأين النعمة؟", "h": ["قبح جريمة القتل عند كافة الناس مؤمنهم وكافرهم، وهو أمر فطري.", "جواز التذكير بالإحسان لمن أنكره، ولكن لا على سبيل الامتنان، فإنه محبط للعمل.", "جواز إطلاق لفظ الضلال على الجهل، كما قال موسى: «وأنا من الضالين» أي الجاهلين قبل أن يعلّمني ربي.", "مشروعية الفرار من الخوف إذا لم يكن في البلد قضاء عادل، وإلا لما جاز الهرب من وجه العدالة."], "k": "«فعلتها إذاً وأنا من الضالين»… اعترف موسى ﵇ بخطئه القديم دون مراوغة؛ فهل أملك هذه الشجاعة؟"}, {"lbl": "الآيات ٢٣ – ٣١", "q": "قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ ﴿٢٣﴾ قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ ﴿٢٤﴾ قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ ﴿٢٥﴾ قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ﴿٢٦﴾ قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ ﴿٢٧﴾ قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ﴿٢٨﴾ قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ ﴿٢٩﴾ قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ ﴿٣٠﴾ قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٣١﴾", "w": [["وما رب العالمين", "الذي تقول إنك رسوله، من أي جنس هو؟"], ["رب السماوات والأرض وما بينهما", "خالق ذلك كله ومالكه."], ["إن كنتم موقنين", "بأن كل مخلوق لا بد له من خالق."], ["لمن حوله", "من أشراف قومه ورجال دولته."], ["ألا تستمعون", "جوابه الذي لم يطابق السؤال في نظره."], ["أوَلو جئتك بشيء مبين", "أتسجنني ولو جئتك ببرهان وحجة على رسالتي؟"], ["فأت به إن كنت من الصادقين", "فيما تدّعي."]], "m": "لما قال موسى: إني رسول رب العالمين، قال فرعون في عناد ومكابرة: وما رب العالمين؟ أي من أي جنس هو؟ فأجابه موسى: رب السماوات والأرض وما بينهما، خالق ذلك كله ومالكه، إن كنتم موقنين بأن كل مخلوق لا بد له من خالق. فقال فرعون في استخفاف لمن حوله: ألا تستمعون؟ كأنما قال موسى أمراً عجباً. فقال موسى: ربكم ورب آبائكم الأولين. فاغتاظ فرعون وقال: إن رسولكم الذي أُرسل إليكم لمجنون. فردّ موسى: رب المشرق والمغرب وما بينهما، رب الكون كله، إن كنتم تعقلون. فقال فرعون: لئن اتخذت إلهاً غيري لأجعلنّك من المسجونين. فقال موسى: أتسجنني ولو جئتك ببرهان ساطع على صدقي؟ قال فرعون: فأت به إن كنت من الصادقين.", "h": ["تقرير الربوبية المقتضية للألوهية من طريق هذا الحوار، ليسمع ذلك المشركون ويعلموا أنهم مسبوقون بالشرك والكفر وأنهم ضالّون.", "سنة أهل الباطل أنهم يفجرون في الخصومة، وفي الحديث: «وإذا خاصم فجر».", "أهل الكبر والعلوّ في الأرض إذا أعيتهم الحجج لجأوا إلى التهديد والوعيد."], "k": "«لأجعلنّك من المسجونين»… حين تنفد الحجة يبدأ التهديد؛ فهل أرفع صوتي حين أعجز عن الإقناع؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (261, 26, 32, 68, 'سورة الشعراء ٣٢ – ٦٨', 'موسى ﵇ والسحرة: «فألقي السحرة ساجدين»، و«قالوا لا ضير»، و«كلا إن معي ربي سيهدين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 261) = $j$[{"lbl": "الآيات ٣٢ – ٤٢", "q": "فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ﴿٣٢﴾ وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّـٰظِرِينَ ﴿٣٣﴾ قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ ﴿٣٤﴾ يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ ﴿٣٥﴾ قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ﴿٣٦﴾ يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ ﴿٣٧﴾ فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ ﴿٣٨﴾ وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ ﴿٣٩﴾ لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ ﴿٤٠﴾ فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ ﴿٤١﴾ قَالَ نَعَمۡ وَإِنَّكُمۡ إِذٗا لَّمِنَ ٱلۡمُقَرَّبِينَ ﴿٤٢﴾", "w": [["ثعبان مبين", "ظاهر أنه ثعبان لا شك فيه."], ["ونزع يده", "أخرجها من جيبه بعد أن أدخلها فيه."], ["لساحر عليم", "متفوّق في علم السحر."], ["أرجه وأخاه", "أخّر أمرهما."], ["حاشرين", "جامعين للسحرة."], ["سحّار عليم", "متفوّق في الفن أكثر من موسى."], ["يوم معلوم", "ضحى يوم الزينة عندهم."], ["هل أنتم مجتمعون", "اجتمعوا كي نتّبع السحرة على دينهم إن كانوا هم الغالبين."], ["وإنكم إذاً لمن المقرّبين", "لكم الأجر، وزيادة مزية القرب."]], "m": "لما طالب فرعون موسى بالآية ألقى عصاه فإذا هي ثعبان ظاهر لا شك فيه، وأخرج يده من جيبه فإذا هي بيضاء بياضاً خارقاً للعادة. واعترف فرعون بأن ذلك خارق لكنه راوغ، فقال للملأ حوله: إن هذا لساحر متفوّق، يريد أن يخرجكم من أرضكم بسحره، تهييجاً لهم، وهذا من المكر السياسي إذ جعل القضية أن موسى يريد الاستيلاء على البلاد. ثم قال كالمستشير: فماذا تأمرون؟ قالوا: أخّر أمرهما، وابعث في مدن المملكة رجالاً يجمعون لك كل سحّار متفوّق. فجمع السحرة لموعد ضحى يوم العيد، وحُثّ الناس على الحضور: لعلنا نتّبع السحرة فنبقى على ديننا إن كانوا هم الغالبين. فلما جاء السحرة قالوا لفرعون: أئن لنا لأجراً إن كنا نحن الغالبين؟ قال: نعم، وإنكم إذاً لمن المقرّبين لدينا، إغراءً لهم ليبذلوا أقصى جهدهم.", "h": ["إثبات المعجزات للأنبياء، كمعجزة العصا واليد لموسى ﵇.", "مشروعية استشارة الأمير رجاله في الأمور ذات البال.", "ثبوت السحر، وأنه فن من فنون المعرفة، وإن كان تعلّمه وتعليمه محرّمين.", "إعطاء المكافأة للفائزين في المباراة وغيرها، ومن ذلك السباق في الإسلام."], "k": "«أئن لنا لأجراً»… جاء السحرة يطلبون أجراً من فرعون، فخرجوا بأجر من الله؛ فممّن أطلب أجري أنا؟"}, {"lbl": "الآيات ٤٣ – ٥١", "q": "قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ﴿٤٣﴾ فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ ﴿٤٤﴾ فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ ﴿٤٥﴾ فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ ﴿٤٦﴾ قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ ﴿٤٧﴾ رَبِّ مُوسَىٰ وَهَٰرُونَ ﴿٤٨﴾ قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ ﴿٤٩﴾ قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ﴿٥٠﴾ إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ ﴿٥١﴾", "w": [["ألقوا ما أنتم ملقون", "أمرهم بالإلقاء توسّلاً إلى ظهور الحق."], ["ما يأفكون", "ما يقلبونه بتمويههم من أن حبالهم وعصيّهم حيّات تسعى."], ["رب موسى وهارون", "لعلمهم بأن ما شاهدوه من العصا لا يأتي بالسحر."], ["من خلاف", "يد كل واحد اليمنى ورجله اليسرى."], ["ولأصلّبنّكم أجمعين", "لأشدّنكم بعد قطع أيديكم وأرجلكم على أعواد الصلب."], ["لا ضير", "لا ضرر علينا."], ["لمنقلبون", "راجعون بعد الموت، وذلك يسرّ ولا يضر."], ["أن كنا أول المؤمنين", "رجوا أن يكفّر الله سيئاتهم لأنهم سبقوا بالإيمان."]], "m": "بعد أن طمأن فرعون السحرة على الأجر قال لهم موسى: ألقوا ما أنتم ملقون، فألقوا حبالهم وعصيّهم وأقسموا بعزّة فرعون إنهم لهم الغالبون، فانقلبت الساحة حيّات وثعابين. فألقى موسى عصاه فإذا هي تبتلع كل ما زوّره السحرة بسحرهم. فألقى السحرة أنفسهم على الأرض ساجدين لله، لما بهرهم من الحق، قالوا: آمنا برب العالمين رب موسى وهارون. فخاف فرعون أن يفلت الزمام من يده، فقال: آمنتم له قبل أن آذن لكم؟ إنه لكبيركم الذي علّمكم السحر، أي تواطأتم معه تضليلاً للجماهير، فلسوف تعلمون عقوبتي: لأقطّعنّ أيديكم وأرجلكم من خلاف ولأصلّبنّكم أجمعين. قالوا: لا ضرر علينا، إنا إلى ربنا راجعون، وكل ما تفعله أنك تعجّل برجوعنا إليه وذلك أحب شيء إلينا، إنا نطمع أن يغفر لنا ربنا خطايانا أن كنا أول المؤمنين في هذه البلاد.", "h": ["لم يبادر موسى بإلقاء عصاه أولاً، لأن المسألة مسألة علم لا حرب، وفي العلم يحسن تقديم الخصم، فإذا أظهر ما عنده كرّ عليه بالحجج فأبطله وظهر الحق.", "من مظاهر الهداية الإلهية هداية السحرة، إذ هم في أول النهار سحرة كفرة، وفي آخره مؤمنون بررة.", "ما سلكه فرعون مع السحرة كله من باب المناورات السياسية الفاشلة.", "قوة الإيمان مصدر شجاعة خارقة للعادة، بحيث يفرح المؤمن بالموت.", "حسن الرجاء في الله والطمع في رحمته، وفضل الأسبقية في الخير."], "k": "«لا ضير إنا إلى ربنا منقلبون»… ساعات من الإيمان صنعت هذا الثبات؛ فماذا صنعت فيّ سنواتي؟"}, {"lbl": "الآيات ٥٢ – ٦٨", "q": "۞وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم مُّتَّبَعُونَ ﴿٥٢﴾ فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ﴿٥٣﴾ إِنَّ هَـٰٓؤُلَآءِ لَشِرۡذِمَةٞ قَلِيلُونَ ﴿٥٤﴾ وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ ﴿٥٥﴾ وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ ﴿٥٦﴾ فَأَخۡرَجۡنَٰهُم مِّن جَنَّـٰتٖ وَعُيُونٖ ﴿٥٧﴾ وَكُنُوزٖ وَمَقَامٖ كَرِيمٖ ﴿٥٨﴾ كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٥٩﴾ فَأَتۡبَعُوهُم مُّشۡرِقِينَ ﴿٦٠﴾ فَلَمَّا تَرَـٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ ﴿٦١﴾ قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ ﴿٦٢﴾ فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ ﴿٦٣﴾ وَأَزۡلَفۡنَا ثَمَّ ٱلۡأٓخَرِينَ ﴿٦٤﴾ وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ ﴿٦٥﴾ ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ ﴿٦٦﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿٦٧﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٦٨﴾", "w": [["أن أسر بعبادي", "السُّرى: المشي ليلاً، والعباد بنو إسرائيل."], ["إنكم متّبعون", "من قِبل فرعون وجيوشه."], ["لشرذمة", "طائفة قليلة من الناس."], ["لغائظون", "فاعلون ما يغيظنا ويغضبنا."], ["حاذرون", "متيقّظون مستعدّون."], ["ومقام كريم", "مجلس حسن كان للأمراء والوزراء."], ["مشرقين", "وقت شروق الشمس."], ["فلما تراءى الجمعان", "رأى بعضهما بعضاً لتقاربهما."], ["إنا لمدركون", "سيلحقنا فرعون وجنده."], ["كالطود العظيم", "كالجبل العظيم."], ["وأزلفنا ثمّ الآخرين", "قرّبنا هنالك فرعون وجنده."]], "m": "بعد هذا الانتصار أوحى الله إلى موسى: أن سر ببني إسرائيل ليلاً، إنكم متّبعون من فرعون وجنوده. فأرسل فرعون في المدائن رجالاً يجمعون الناس، في تعبئة عامة، يقولون: إن هؤلاء لطائفة قليلة، وإنهم لفاعلون ما يغيظنا، وإنا لجميع متيقّظون مستعدّون. قال تعالى: فأخرجناهم من جنات وعيون وكنوز ومجلس كريم، كذلك، وأورثنا تلك النعم بني إسرائيل بعد هلاك فرعون. فتبعوهم وقت شروق الشمس. فلما تراءى الجمعان قال أصحاب موسى خائفين: إنا لمدركون! فطمأنهم موسى: كلا، إن معي ربي سيهديني إلى طريق النجاة. فأوحينا إليه أن اضرب بعصاك البحر، فانفلق فرقتين، كل فرقة كالجبل العظيم، وقرّبنا هنالك فرعون وجنوده، وأنجينا موسى ومن معه أجمعين، ثم أغرقنا الآخرين. إن في ذلك لآية على ربوبية الله وقدرته، وما كان أكثر قومك مؤمنين، وإن ربك لهو العزيز الرحيم، فاصبر وتوكّل عليه.", "h": ["مشروعية التعبئة العامة، واستعمال أسلوب خاص في الحرب يهدّئ من مخاوف الأمة.", "ظهور آثار الاستعباد في بني إسرائيل، متجلّية في خوفهم مع مشاهدة الآيات.", "ثبوت صفة المعيّة الإلهية في قول موسى: «إن معي ربي».", "انفلاق البحر من أعظم الآيات.", "تقرير نبوة محمد ﷺ بقصّه مثل هذا القصص الذي لا يتأتّى إلا بوحي خاص."], "k": "«كلا إن معي ربي سيهدين»… البحر أمامه والعدوّ خلفه، ويقينه أكبر منهما؛ فما بحري اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 261;
insert into public.tdb_cards(topic, i, body) select 261, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٢ – ٤٢", "q": "فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ﴿٣٢﴾ وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّـٰظِرِينَ ﴿٣٣﴾ قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ ﴿٣٤﴾ يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ ﴿٣٥﴾ قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ﴿٣٦﴾ يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ ﴿٣٧﴾ فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ ﴿٣٨﴾ وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ ﴿٣٩﴾ لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ ﴿٤٠﴾ فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ ﴿٤١﴾ قَالَ نَعَمۡ وَإِنَّكُمۡ إِذٗا لَّمِنَ ٱلۡمُقَرَّبِينَ ﴿٤٢﴾", "w": [["ثعبان مبين", "ظاهر أنه ثعبان لا شك فيه."], ["ونزع يده", "أخرجها من جيبه بعد أن أدخلها فيه."], ["لساحر عليم", "متفوّق في علم السحر."], ["أرجه وأخاه", "أخّر أمرهما."], ["حاشرين", "جامعين للسحرة."], ["سحّار عليم", "متفوّق في الفن أكثر من موسى."], ["يوم معلوم", "ضحى يوم الزينة عندهم."], ["هل أنتم مجتمعون", "اجتمعوا كي نتّبع السحرة على دينهم إن كانوا هم الغالبين."], ["وإنكم إذاً لمن المقرّبين", "لكم الأجر، وزيادة مزية القرب."]], "m": "لما طالب فرعون موسى بالآية ألقى عصاه فإذا هي ثعبان ظاهر لا شك فيه، وأخرج يده من جيبه فإذا هي بيضاء بياضاً خارقاً للعادة. واعترف فرعون بأن ذلك خارق لكنه راوغ، فقال للملأ حوله: إن هذا لساحر متفوّق، يريد أن يخرجكم من أرضكم بسحره، تهييجاً لهم، وهذا من المكر السياسي إذ جعل القضية أن موسى يريد الاستيلاء على البلاد. ثم قال كالمستشير: فماذا تأمرون؟ قالوا: أخّر أمرهما، وابعث في مدن المملكة رجالاً يجمعون لك كل سحّار متفوّق. فجمع السحرة لموعد ضحى يوم العيد، وحُثّ الناس على الحضور: لعلنا نتّبع السحرة فنبقى على ديننا إن كانوا هم الغالبين. فلما جاء السحرة قالوا لفرعون: أئن لنا لأجراً إن كنا نحن الغالبين؟ قال: نعم، وإنكم إذاً لمن المقرّبين لدينا، إغراءً لهم ليبذلوا أقصى جهدهم.", "h": ["إثبات المعجزات للأنبياء، كمعجزة العصا واليد لموسى ﵇.", "مشروعية استشارة الأمير رجاله في الأمور ذات البال.", "ثبوت السحر، وأنه فن من فنون المعرفة، وإن كان تعلّمه وتعليمه محرّمين.", "إعطاء المكافأة للفائزين في المباراة وغيرها، ومن ذلك السباق في الإسلام."], "k": "«أئن لنا لأجراً»… جاء السحرة يطلبون أجراً من فرعون، فخرجوا بأجر من الله؛ فممّن أطلب أجري أنا؟"}, {"lbl": "الآيات ٤٣ – ٥١", "q": "قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ﴿٤٣﴾ فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ ﴿٤٤﴾ فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ ﴿٤٥﴾ فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ ﴿٤٦﴾ قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ ﴿٤٧﴾ رَبِّ مُوسَىٰ وَهَٰرُونَ ﴿٤٨﴾ قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ ﴿٤٩﴾ قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ﴿٥٠﴾ إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ ﴿٥١﴾", "w": [["ألقوا ما أنتم ملقون", "أمرهم بالإلقاء توسّلاً إلى ظهور الحق."], ["ما يأفكون", "ما يقلبونه بتمويههم من أن حبالهم وعصيّهم حيّات تسعى."], ["رب موسى وهارون", "لعلمهم بأن ما شاهدوه من العصا لا يأتي بالسحر."], ["من خلاف", "يد كل واحد اليمنى ورجله اليسرى."], ["ولأصلّبنّكم أجمعين", "لأشدّنكم بعد قطع أيديكم وأرجلكم على أعواد الصلب."], ["لا ضير", "لا ضرر علينا."], ["لمنقلبون", "راجعون بعد الموت، وذلك يسرّ ولا يضر."], ["أن كنا أول المؤمنين", "رجوا أن يكفّر الله سيئاتهم لأنهم سبقوا بالإيمان."]], "m": "بعد أن طمأن فرعون السحرة على الأجر قال لهم موسى: ألقوا ما أنتم ملقون، فألقوا حبالهم وعصيّهم وأقسموا بعزّة فرعون إنهم لهم الغالبون، فانقلبت الساحة حيّات وثعابين. فألقى موسى عصاه فإذا هي تبتلع كل ما زوّره السحرة بسحرهم. فألقى السحرة أنفسهم على الأرض ساجدين لله، لما بهرهم من الحق، قالوا: آمنا برب العالمين رب موسى وهارون. فخاف فرعون أن يفلت الزمام من يده، فقال: آمنتم له قبل أن آذن لكم؟ إنه لكبيركم الذي علّمكم السحر، أي تواطأتم معه تضليلاً للجماهير، فلسوف تعلمون عقوبتي: لأقطّعنّ أيديكم وأرجلكم من خلاف ولأصلّبنّكم أجمعين. قالوا: لا ضرر علينا، إنا إلى ربنا راجعون، وكل ما تفعله أنك تعجّل برجوعنا إليه وذلك أحب شيء إلينا، إنا نطمع أن يغفر لنا ربنا خطايانا أن كنا أول المؤمنين في هذه البلاد.", "h": ["لم يبادر موسى بإلقاء عصاه أولاً، لأن المسألة مسألة علم لا حرب، وفي العلم يحسن تقديم الخصم، فإذا أظهر ما عنده كرّ عليه بالحجج فأبطله وظهر الحق.", "من مظاهر الهداية الإلهية هداية السحرة، إذ هم في أول النهار سحرة كفرة، وفي آخره مؤمنون بررة.", "ما سلكه فرعون مع السحرة كله من باب المناورات السياسية الفاشلة.", "قوة الإيمان مصدر شجاعة خارقة للعادة، بحيث يفرح المؤمن بالموت.", "حسن الرجاء في الله والطمع في رحمته، وفضل الأسبقية في الخير."], "k": "«لا ضير إنا إلى ربنا منقلبون»… ساعات من الإيمان صنعت هذا الثبات؛ فماذا صنعت فيّ سنواتي؟"}, {"lbl": "الآيات ٥٢ – ٦٨", "q": "۞وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم مُّتَّبَعُونَ ﴿٥٢﴾ فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ﴿٥٣﴾ إِنَّ هَـٰٓؤُلَآءِ لَشِرۡذِمَةٞ قَلِيلُونَ ﴿٥٤﴾ وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ ﴿٥٥﴾ وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ ﴿٥٦﴾ فَأَخۡرَجۡنَٰهُم مِّن جَنَّـٰتٖ وَعُيُونٖ ﴿٥٧﴾ وَكُنُوزٖ وَمَقَامٖ كَرِيمٖ ﴿٥٨﴾ كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿٥٩﴾ فَأَتۡبَعُوهُم مُّشۡرِقِينَ ﴿٦٠﴾ فَلَمَّا تَرَـٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ ﴿٦١﴾ قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ ﴿٦٢﴾ فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ ﴿٦٣﴾ وَأَزۡلَفۡنَا ثَمَّ ٱلۡأٓخَرِينَ ﴿٦٤﴾ وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ ﴿٦٥﴾ ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ ﴿٦٦﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿٦٧﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٦٨﴾", "w": [["أن أسر بعبادي", "السُّرى: المشي ليلاً، والعباد بنو إسرائيل."], ["إنكم متّبعون", "من قِبل فرعون وجيوشه."], ["لشرذمة", "طائفة قليلة من الناس."], ["لغائظون", "فاعلون ما يغيظنا ويغضبنا."], ["حاذرون", "متيقّظون مستعدّون."], ["ومقام كريم", "مجلس حسن كان للأمراء والوزراء."], ["مشرقين", "وقت شروق الشمس."], ["فلما تراءى الجمعان", "رأى بعضهما بعضاً لتقاربهما."], ["إنا لمدركون", "سيلحقنا فرعون وجنده."], ["كالطود العظيم", "كالجبل العظيم."], ["وأزلفنا ثمّ الآخرين", "قرّبنا هنالك فرعون وجنده."]], "m": "بعد هذا الانتصار أوحى الله إلى موسى: أن سر ببني إسرائيل ليلاً، إنكم متّبعون من فرعون وجنوده. فأرسل فرعون في المدائن رجالاً يجمعون الناس، في تعبئة عامة، يقولون: إن هؤلاء لطائفة قليلة، وإنهم لفاعلون ما يغيظنا، وإنا لجميع متيقّظون مستعدّون. قال تعالى: فأخرجناهم من جنات وعيون وكنوز ومجلس كريم، كذلك، وأورثنا تلك النعم بني إسرائيل بعد هلاك فرعون. فتبعوهم وقت شروق الشمس. فلما تراءى الجمعان قال أصحاب موسى خائفين: إنا لمدركون! فطمأنهم موسى: كلا، إن معي ربي سيهديني إلى طريق النجاة. فأوحينا إليه أن اضرب بعصاك البحر، فانفلق فرقتين، كل فرقة كالجبل العظيم، وقرّبنا هنالك فرعون وجنوده، وأنجينا موسى ومن معه أجمعين، ثم أغرقنا الآخرين. إن في ذلك لآية على ربوبية الله وقدرته، وما كان أكثر قومك مؤمنين، وإن ربك لهو العزيز الرحيم، فاصبر وتوكّل عليه.", "h": ["مشروعية التعبئة العامة، واستعمال أسلوب خاص في الحرب يهدّئ من مخاوف الأمة.", "ظهور آثار الاستعباد في بني إسرائيل، متجلّية في خوفهم مع مشاهدة الآيات.", "ثبوت صفة المعيّة الإلهية في قول موسى: «إن معي ربي».", "انفلاق البحر من أعظم الآيات.", "تقرير نبوة محمد ﷺ بقصّه مثل هذا القصص الذي لا يتأتّى إلا بوحي خاص."], "k": "«كلا إن معي ربي سيهدين»… البحر أمامه والعدوّ خلفه، ويقينه أكبر منهما؛ فما بحري اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (262, 26, 69, 104, 'سورة الشعراء ٦٩ – ١٠٤', '«واتل عليهم نبأ إبراهيم»، و«الذي خلقني فهو يهدين»، و«إلا من أتى الله بقلب سليم»، وخصومة أهل النار', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 262) = $j$[{"lbl": "الآيات ٦٩ – ٨٢", "q": "وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ ﴿٦٩﴾ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ ﴿٧٠﴾ قَالُواْ نَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ ﴿٧١﴾ قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ ﴿٧٢﴾ أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ ﴿٧٣﴾ قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ ﴿٧٤﴾ قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ ﴿٧٥﴾ أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ ﴿٧٦﴾ فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ ﴿٧٧﴾ ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ ﴿٧٨﴾ وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ ﴿٧٩﴾ وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ﴿٨٠﴾ وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ ﴿٨١﴾ وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ ﴿٨٢﴾", "w": [["واتل عليهم نبأ إبراهيم", "اقرأ على قومك خبر إبراهيم وشأنه العظيم."], ["لأبيه وقومه", "آزر والبابليين."], ["فنظلّ لها عاكفين", "نقيم أكثر النهار عاكفين على عبادتها."], ["بل وجدنا آباءنا", "لا تسمع ولا تنفع ولا تضر، بل وجدنا آباءنا لها عابدين فنحن نعبدها."], ["فإنهم عدوّ لي", "أعداء لي يوم القيامة إن أنا عبدتهم، لأنهم يتبرّؤون ممن عبدهم."], ["إلا رب العالمين", "فإن من يعبده لا يتبرّأ منه، بل ينجيه من النار ويكرمه."], ["فهو يهدين", "إلى ما ينجيني من العذاب ويسعدني في دنياي وأخراي."], ["والذي يميتني ثم يحيين", "يميتني عند انتهاء أجلي، ثم يحييني ليوم الدين."], ["يوم الدين", "يوم الجزاء والحساب."]], "m": "هذا بداية قصص إبراهيم ﵇، عرضاً لحياته الدعوية على قريش لعلهم يتّعظون. اقرأ على قومك خبر إبراهيم إذ قال لأبيه وقومه: ما تعبدون؟ مستفهماً ليردّ على جوابهم، وهو أسلوب حكيم في الدعوة والتعليم. قالوا: نعبد تماثيل فنقيم أكثر النهار عاكفين حولها. قال: هل يسمعونكم إذ تدعونهم، أو ينفعونكم أو يضرّون؟ فأجابوا: لا، ولكنا وجدنا آباءنا كذلك يفعلون. فصارحهم: أفرأيتم ما كنتم تعبدون أنتم وآباؤكم الأقدمون؟ فإنهم أعداء لي يوم القيامة إن عبدتهم، لأن كل من عُبد من دون الله يتبرّأ ممن عبده، إلا رب العالمين، فإنه ودود رحيم بمن عبده. ثم أخذ يُثني على ربه تعريفاً به: الذي خلقني فهو يهديني إلى طريق نجاتي ببيان محابّه ومساخطه، والذي هو يطعمني ويسقيني، وإذا مرضت فهو لا غيره يشفيني، والذي يميتني عند انتهاء أجلي ثم يحييني يوم البعث، والذي أطمع أن يغفر لي خطيئتي يوم الجزاء.", "h": ["تقرير النبوة المحمدية بذكر هذا القصص.", "تقرير التوحيد بالحوار الذي دار بين إبراهيم إمام الموحّدين وقومه المشركين.", "بيان أن كل من عبد معبوداً غير الله تعالى سيكون له عدواً لدوداً يوم القيامة.", "بيان الأسلوب الحكيم في الدعوة إلى الله تعالى من طريق السؤال والجواب."], "k": "«وإذا مرضت فهو يشفين»… نسب إبراهيم ﵇ المرض لنفسه والشفاء لربه؛ فبمن يتعلّق قلبي حين أمرض؟"}, {"lbl": "الآيات ٨٣ – ٩٣", "q": "رَبِّ هَبۡ لِي حُكۡمٗا وَأَلۡحِقۡنِي بِٱلصَّـٰلِحِينَ ﴿٨٣﴾ وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ ﴿٨٤﴾ وَٱجۡعَلۡنِي مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ ﴿٨٥﴾ وَٱغۡفِرۡ لِأَبِيٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ ﴿٨٦﴾ وَلَا تُخۡزِنِي يَوۡمَ يُبۡعَثُونَ ﴿٨٧﴾ يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ ﴿٨٨﴾ إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ ﴿٨٩﴾ وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ ﴿٩٠﴾ وَبُرِّزَتِ ٱلۡجَحِيمُ لِلۡغَاوِينَ ﴿٩١﴾ وَقِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تَعۡبُدُونَ ﴿٩٢﴾ مِن دُونِ ٱللَّهِ هَلۡ يَنصُرُونَكُمۡ أَوۡ يَنتَصِرُونَ ﴿٩٣﴾", "w": [["هب لي حكماً", "علماً نافعاً يمنعني من فعل ما يسخطك."], ["وألحقني بالصالحين", "في أعمالهم في الدنيا، وبمرافقتهم في الجنة."], ["لسان صدق في الآخرين", "ذكراً حسناً فيمن يأتي من عبادك المؤمنين."], ["من الضالين", "الجاهلين بك وبمحابّك ومكارهك."], ["ولا تخزني", "لا تذلّني."], ["بقلب سليم", "سليم من الشرك والنفاق."], ["وأُزلفت الجنة", "قُرّبت وأُدنيت للمتقين."], ["وبرّزت الجحيم للغاوين", "أُظهرت وجُلّيت لأهل الغواية والضلال."], ["هل ينصرونكم", "بدفع العذاب عنكم."]], "m": "لما ذكّر إبراهيم قومه رفع يديه إلى ربه متضرّعاً: رب هب لي علماً نافعاً يمنعني مما يسخطك ويدفعني إلى ما يرضيك، وألحقني بالصالحين في أعمالهم في الدنيا وبمرافقتهم في الجنة، واجعل لي ذكراً حسناً فيمن يأتي بعدي، واجعلني من ورثة جنة النعيم الذين يرثونها بالإيمان والتقوى، واغفر لأبي إنه كان من الجاهلين بك، وكان هذا قبل أن يعلم أنه عدو لله فتبرّأ منه، ولا تذلّني يوم يُبعثون، يوم لا ينفع مال ولا بنون، إلا من أتى الله بقلب سليم من الشرك والنفاق، فهذا ينفعه عمله الصالح لخلوّه مما يحبطه. وقُرّبت الجنة للمتقين، وأُظهرت الجحيم لأهل الغواية من المشركين والمسرفين في الإجرام، وسُئلوا: أين ما كنتم تعبدون من دون الله؟ هل يدفعون عنكم العذاب أو يدفعونه عن أنفسهم؟", "h": ["بيان أن الجنة تورث، وسبب إرثها التقوى، كما في قوله: «تلك الجنة التي نورث من عبادنا من كان تقياً».", "مشروعية الاستغفار للوالدين إن ماتا على التوحيد.", "بطلان الانتفاع يوم القيامة بغير الإيمان والعمل الصالح بعد فضل الله ورحمته.", "الترغيب في التقوى، والتحذير من الغواية."], "k": "«إلا من أتى الله بقلب سليم»… لا مال ولا ولد يومها؛ فما الذي ينقص قلبي ليكون سليماً؟"}, {"lbl": "الآيات ٩٤ – ١٠٤", "q": "فَكُبۡكِبُواْ فِيهَا هُمۡ وَٱلۡغَاوُۥنَ ﴿٩٤﴾ وَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ ﴿٩٥﴾ قَالُواْ وَهُمۡ فِيهَا يَخۡتَصِمُونَ ﴿٩٦﴾ تَٱللَّهِ إِن كُنَّا لَفِي ضَلَٰلٖ مُّبِينٍ ﴿٩٧﴾ إِذۡ نُسَوِّيكُم بِرَبِّ ٱلۡعَٰلَمِينَ ﴿٩٨﴾ وَمَآ أَضَلَّنَآ إِلَّا ٱلۡمُجۡرِمُونَ ﴿٩٩﴾ فَمَا لَنَا مِن شَٰفِعِينَ ﴿١٠٠﴾ وَلَا صَدِيقٍ حَمِيمٖ ﴿١٠١﴾ فَلَوۡ أَنَّ لَنَا كَرَّةٗ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿١٠٢﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٠٣﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٠٤﴾", "w": [["فكُبكبوا فيها", "أُلقوا على وجوههم في جهنم ودُحرجوا حتى انتهوا إلى قعرها."], ["والغاوون", "جمع غاوٍ، وهو الفاسد القلب المدنّس الروح بالشرك والمعاصي."], ["وجنود إبليس", "أتباعه وأنصاره وأعوانه من الإنس والجن."], ["إذ نسوّيكم برب العالمين", "في العبادة، فعبدناكم كما يُعبد الله."], ["ولا صديق حميم", "يهمّه أمرنا وتنفعنا صداقته."], ["فلو أن لنا كرّة", "رجعة إلى الدنيا لنؤمن ونوحّد ونعبد ربنا بما شرع لنا."]], "m": "بعد ذلك السؤال التوبيخي الذي عجزوا عن جوابه أخبر تعالى أنهم كُبكبوا في جهنم على وجوههم، هم والغاوون وجنود إبليس أجمعون من أعوان الشيطان من الإنس والجن. قالوا وهم فيها يختصمون، كل يحمّل الآخر التبعة، قال المشركون لمن أشركوا بهم: تالله إن كنا لفي ضلال ظاهر إذ نسوّيكم برب العالمين فنعبدكم معه، وما أضلّنا إلا المجرمون، دعاة الشرك والشر الذين أفسدوا أنفسهم وأفسدونا. فما لنا من شافعين يشفعون لنا، إذ لا شفاعة تنفع من مات على الشرك، ولا صديق حميم تنفعنا صداقته. فلو أن لنا رجعة إلى الدنيا فنكون من المؤمنين. إن في ذلك لعبرة لمن يعتبر، وما كان أكثر قومك مؤمنين، وإن ربك لهو العزيز الرحيم.", "h": ["تقرير أن دعاة الزنى والربا والخرافة والشركيات من الناس هم من جند إبليس.", "تقرير أن المجرمين هم الذين أفسدوا نفوسهم ونفوس غيرهم بدعوتهم إلى الضلال وحملهم على المعاصي.", "تقرير أن الشفاعة لن تكون لمن مات على الشرك والكفر.", "لا تنفع العبر والمواعظ والآيات في هداية قوم علم الله منهم أنهم لا يؤمنون."], "k": "«فلو أن لنا كرّة»… ما يتمنّاه أهل النار أملكه الآن؛ فماذا أفعل بفرصتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 262;
insert into public.tdb_cards(topic, i, body) select 262, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٩ – ٨٢", "q": "وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ ﴿٦٩﴾ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ ﴿٧٠﴾ قَالُواْ نَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ ﴿٧١﴾ قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ ﴿٧٢﴾ أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ ﴿٧٣﴾ قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ ﴿٧٤﴾ قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ ﴿٧٥﴾ أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ ﴿٧٦﴾ فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ ﴿٧٧﴾ ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ ﴿٧٨﴾ وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ ﴿٧٩﴾ وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ﴿٨٠﴾ وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ ﴿٨١﴾ وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ ﴿٨٢﴾", "w": [["واتل عليهم نبأ إبراهيم", "اقرأ على قومك خبر إبراهيم وشأنه العظيم."], ["لأبيه وقومه", "آزر والبابليين."], ["فنظلّ لها عاكفين", "نقيم أكثر النهار عاكفين على عبادتها."], ["بل وجدنا آباءنا", "لا تسمع ولا تنفع ولا تضر، بل وجدنا آباءنا لها عابدين فنحن نعبدها."], ["فإنهم عدوّ لي", "أعداء لي يوم القيامة إن أنا عبدتهم، لأنهم يتبرّؤون ممن عبدهم."], ["إلا رب العالمين", "فإن من يعبده لا يتبرّأ منه، بل ينجيه من النار ويكرمه."], ["فهو يهدين", "إلى ما ينجيني من العذاب ويسعدني في دنياي وأخراي."], ["والذي يميتني ثم يحيين", "يميتني عند انتهاء أجلي، ثم يحييني ليوم الدين."], ["يوم الدين", "يوم الجزاء والحساب."]], "m": "هذا بداية قصص إبراهيم ﵇، عرضاً لحياته الدعوية على قريش لعلهم يتّعظون. اقرأ على قومك خبر إبراهيم إذ قال لأبيه وقومه: ما تعبدون؟ مستفهماً ليردّ على جوابهم، وهو أسلوب حكيم في الدعوة والتعليم. قالوا: نعبد تماثيل فنقيم أكثر النهار عاكفين حولها. قال: هل يسمعونكم إذ تدعونهم، أو ينفعونكم أو يضرّون؟ فأجابوا: لا، ولكنا وجدنا آباءنا كذلك يفعلون. فصارحهم: أفرأيتم ما كنتم تعبدون أنتم وآباؤكم الأقدمون؟ فإنهم أعداء لي يوم القيامة إن عبدتهم، لأن كل من عُبد من دون الله يتبرّأ ممن عبده، إلا رب العالمين، فإنه ودود رحيم بمن عبده. ثم أخذ يُثني على ربه تعريفاً به: الذي خلقني فهو يهديني إلى طريق نجاتي ببيان محابّه ومساخطه، والذي هو يطعمني ويسقيني، وإذا مرضت فهو لا غيره يشفيني، والذي يميتني عند انتهاء أجلي ثم يحييني يوم البعث، والذي أطمع أن يغفر لي خطيئتي يوم الجزاء.", "h": ["تقرير النبوة المحمدية بذكر هذا القصص.", "تقرير التوحيد بالحوار الذي دار بين إبراهيم إمام الموحّدين وقومه المشركين.", "بيان أن كل من عبد معبوداً غير الله تعالى سيكون له عدواً لدوداً يوم القيامة.", "بيان الأسلوب الحكيم في الدعوة إلى الله تعالى من طريق السؤال والجواب."], "k": "«وإذا مرضت فهو يشفين»… نسب إبراهيم ﵇ المرض لنفسه والشفاء لربه؛ فبمن يتعلّق قلبي حين أمرض؟"}, {"lbl": "الآيات ٨٣ – ٩٣", "q": "رَبِّ هَبۡ لِي حُكۡمٗا وَأَلۡحِقۡنِي بِٱلصَّـٰلِحِينَ ﴿٨٣﴾ وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ ﴿٨٤﴾ وَٱجۡعَلۡنِي مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ ﴿٨٥﴾ وَٱغۡفِرۡ لِأَبِيٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ ﴿٨٦﴾ وَلَا تُخۡزِنِي يَوۡمَ يُبۡعَثُونَ ﴿٨٧﴾ يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ ﴿٨٨﴾ إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ ﴿٨٩﴾ وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ ﴿٩٠﴾ وَبُرِّزَتِ ٱلۡجَحِيمُ لِلۡغَاوِينَ ﴿٩١﴾ وَقِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تَعۡبُدُونَ ﴿٩٢﴾ مِن دُونِ ٱللَّهِ هَلۡ يَنصُرُونَكُمۡ أَوۡ يَنتَصِرُونَ ﴿٩٣﴾", "w": [["هب لي حكماً", "علماً نافعاً يمنعني من فعل ما يسخطك."], ["وألحقني بالصالحين", "في أعمالهم في الدنيا، وبمرافقتهم في الجنة."], ["لسان صدق في الآخرين", "ذكراً حسناً فيمن يأتي من عبادك المؤمنين."], ["من الضالين", "الجاهلين بك وبمحابّك ومكارهك."], ["ولا تخزني", "لا تذلّني."], ["بقلب سليم", "سليم من الشرك والنفاق."], ["وأُزلفت الجنة", "قُرّبت وأُدنيت للمتقين."], ["وبرّزت الجحيم للغاوين", "أُظهرت وجُلّيت لأهل الغواية والضلال."], ["هل ينصرونكم", "بدفع العذاب عنكم."]], "m": "لما ذكّر إبراهيم قومه رفع يديه إلى ربه متضرّعاً: رب هب لي علماً نافعاً يمنعني مما يسخطك ويدفعني إلى ما يرضيك، وألحقني بالصالحين في أعمالهم في الدنيا وبمرافقتهم في الجنة، واجعل لي ذكراً حسناً فيمن يأتي بعدي، واجعلني من ورثة جنة النعيم الذين يرثونها بالإيمان والتقوى، واغفر لأبي إنه كان من الجاهلين بك، وكان هذا قبل أن يعلم أنه عدو لله فتبرّأ منه، ولا تذلّني يوم يُبعثون، يوم لا ينفع مال ولا بنون، إلا من أتى الله بقلب سليم من الشرك والنفاق، فهذا ينفعه عمله الصالح لخلوّه مما يحبطه. وقُرّبت الجنة للمتقين، وأُظهرت الجحيم لأهل الغواية من المشركين والمسرفين في الإجرام، وسُئلوا: أين ما كنتم تعبدون من دون الله؟ هل يدفعون عنكم العذاب أو يدفعونه عن أنفسهم؟", "h": ["بيان أن الجنة تورث، وسبب إرثها التقوى، كما في قوله: «تلك الجنة التي نورث من عبادنا من كان تقياً».", "مشروعية الاستغفار للوالدين إن ماتا على التوحيد.", "بطلان الانتفاع يوم القيامة بغير الإيمان والعمل الصالح بعد فضل الله ورحمته.", "الترغيب في التقوى، والتحذير من الغواية."], "k": "«إلا من أتى الله بقلب سليم»… لا مال ولا ولد يومها؛ فما الذي ينقص قلبي ليكون سليماً؟"}, {"lbl": "الآيات ٩٤ – ١٠٤", "q": "فَكُبۡكِبُواْ فِيهَا هُمۡ وَٱلۡغَاوُۥنَ ﴿٩٤﴾ وَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ ﴿٩٥﴾ قَالُواْ وَهُمۡ فِيهَا يَخۡتَصِمُونَ ﴿٩٦﴾ تَٱللَّهِ إِن كُنَّا لَفِي ضَلَٰلٖ مُّبِينٍ ﴿٩٧﴾ إِذۡ نُسَوِّيكُم بِرَبِّ ٱلۡعَٰلَمِينَ ﴿٩٨﴾ وَمَآ أَضَلَّنَآ إِلَّا ٱلۡمُجۡرِمُونَ ﴿٩٩﴾ فَمَا لَنَا مِن شَٰفِعِينَ ﴿١٠٠﴾ وَلَا صَدِيقٍ حَمِيمٖ ﴿١٠١﴾ فَلَوۡ أَنَّ لَنَا كَرَّةٗ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿١٠٢﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٠٣﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٠٤﴾", "w": [["فكُبكبوا فيها", "أُلقوا على وجوههم في جهنم ودُحرجوا حتى انتهوا إلى قعرها."], ["والغاوون", "جمع غاوٍ، وهو الفاسد القلب المدنّس الروح بالشرك والمعاصي."], ["وجنود إبليس", "أتباعه وأنصاره وأعوانه من الإنس والجن."], ["إذ نسوّيكم برب العالمين", "في العبادة، فعبدناكم كما يُعبد الله."], ["ولا صديق حميم", "يهمّه أمرنا وتنفعنا صداقته."], ["فلو أن لنا كرّة", "رجعة إلى الدنيا لنؤمن ونوحّد ونعبد ربنا بما شرع لنا."]], "m": "بعد ذلك السؤال التوبيخي الذي عجزوا عن جوابه أخبر تعالى أنهم كُبكبوا في جهنم على وجوههم، هم والغاوون وجنود إبليس أجمعون من أعوان الشيطان من الإنس والجن. قالوا وهم فيها يختصمون، كل يحمّل الآخر التبعة، قال المشركون لمن أشركوا بهم: تالله إن كنا لفي ضلال ظاهر إذ نسوّيكم برب العالمين فنعبدكم معه، وما أضلّنا إلا المجرمون، دعاة الشرك والشر الذين أفسدوا أنفسهم وأفسدونا. فما لنا من شافعين يشفعون لنا، إذ لا شفاعة تنفع من مات على الشرك، ولا صديق حميم تنفعنا صداقته. فلو أن لنا رجعة إلى الدنيا فنكون من المؤمنين. إن في ذلك لعبرة لمن يعتبر، وما كان أكثر قومك مؤمنين، وإن ربك لهو العزيز الرحيم.", "h": ["تقرير أن دعاة الزنى والربا والخرافة والشركيات من الناس هم من جند إبليس.", "تقرير أن المجرمين هم الذين أفسدوا نفوسهم ونفوس غيرهم بدعوتهم إلى الضلال وحملهم على المعاصي.", "تقرير أن الشفاعة لن تكون لمن مات على الشرك والكفر.", "لا تنفع العبر والمواعظ والآيات في هداية قوم علم الله منهم أنهم لا يؤمنون."], "k": "«فلو أن لنا كرّة»… ما يتمنّاه أهل النار أملكه الآن؛ فماذا أفعل بفرصتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (263, 26, 105, 122, 'سورة الشعراء ١٠٥ – ١٢٢', '«كذّبت قوم نوح المرسلين»: «أنؤمن لك واتبعك الأرذلون»، و«ربّ إن قومي كذّبون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 263) = $j$[{"lbl": "الآيات ١٠٥ – ١١٥", "q": "كَذَّبَتۡ قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِينَ ﴿١٠٥﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ ﴿١٠٦﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٠٧﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٠٨﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٠٩﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١١٠﴾ ۞قَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ ﴿١١١﴾ قَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ ﴿١١٢﴾ إِنۡ حِسَابُهُمۡ إِلَّا عَلَىٰ رَبِّيۖ لَوۡ تَشۡعُرُونَ ﴿١١٣﴾ وَمَآ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِينَ ﴿١١٤﴾ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ ﴿١١٥﴾", "w": [["كذّبت قوم نوح المرسلين", "المراد نوح ﵇، ومن كذّب رسولاً فكأنما كذّب الرسل جميعاً."], ["أخوهم نوح", "في النسب."], ["ألا تتقون", "اتقوا الله ربكم فلا تعصوه بالشرك والمعاصي."], ["رسول أمين", "على ما أمرني ربي بإبلاغه إليكم."], ["وما أسألكم عليه من أجر", "لا أسألكم على إبلاغ رسالة الله أجرة."], ["واتبعك الأرذلون", "أراذل الناس وسفلتهم."], ["إن حسابهم إلا على ربي", "ما حسابهم إلا على ربي."]], "m": "هذه بداية قصص نوح ﵇: كذّبت قوم نوح بما جاءهم به من التوحيد، إذ قال لهم أخوهم في النسب: ألا تتقون عقاب الله وأنتم تشركون به؟ إني لكم رسول أمين على ما أبلّغكم، فاتقوا الله وأطيعوني، وما أسألكم على البلاغ من أجر، إن أجري إلا على الله الذي كلّفني. فكان جوابهم: أنصدّقك ونتّبعك وقد اتّبعك سفلة الناس؟ فأجابهم نوح: وما علمي بما كانوا يعملون؟ لا أعلمه ولا أُسأل عنه، إن حسابهم إلا على ربي، هو الذي يحاسبهم ويجزيهم، لو تشعرون بهذه الحقيقة لما عبتموهم لي. وما أنا بطارد المؤمنين من حولي، إن أنا إلا نذير مبين، لست بجبّار ولا ذي سلطان فأطرد الناس، وظيفتي أن أنذر الناس عاقبة الكفر والمعاصي.", "h": ["بيان أن من كذّب رسولاً فكأنما كذّب كل الرسل، باعتبار أن دعوتهم واحدة.", "إثبات أخوّة النسب، ولا تعارض بينها وبين أخوّة الدين.", "عدم جواز أخذ أجرة على دعوة الله تعالى، ووجوب إبلاغها مجاناً.", "وجوب التقوى لله تعالى، وطاعة الرسول ﷺ.", "لا يجوز طرد الفقراء من مجالس العلم ليجلس مجالسهم الأغنياء وأهل الجاه."], "k": "«وما أنا بطارد المؤمنين»… هل أزن الناس بمكانتهم، أم بما في قلوبهم من إيمان؟"}, {"lbl": "الآيات ١١٦ – ١٢٢", "q": "قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلۡمَرۡجُومِينَ ﴿١١٦﴾ قَالَ رَبِّ إِنَّ قَوۡمِي كَذَّبُونِ ﴿١١٧﴾ فَٱفۡتَحۡ بَيۡنِي وَبَيۡنَهُمۡ فَتۡحٗا وَنَجِّنِي وَمَن مَّعِيَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿١١٨﴾ فَأَنجَيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ﴿١١٩﴾ ثُمَّ أَغۡرَقۡنَا بَعۡدُ ٱلۡبَاقِينَ ﴿١٢٠﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٢١﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٢٢﴾", "w": [["لئن لم تنته يا نوح", "عن تسفيه ديننا وسبّ آلهتنا."], ["من المرجومين", "المقتولين رجماً بالحجارة."], ["فافتح بيني وبينهم فتحاً", "احكم بيني وبينهم حكماً بأن تهلكهم وتنجيني ومن معي."], ["في الفلك المشحون", "المملوء بالركاب وأزواج المخلوقات."], ["بعد الباقين", "أغرقنا الكافرين بعد إنجاء نوح والمؤمنين في السفينة."]], "m": "لما دعاهم نوح إلى التوحيد وكرّر عليهم الدعوة وأعيتهم الحجج لجأوا إلى التهديد فقالوا: قسماً لئن لم تنته يا نوح عن تسفيهنا وسبّ آلهتنا لنقتلنّك رمياً بالحجارة. وهنا، بعد دعوة دامت ألف سنة إلا خمسين عاماً، رفع نوح شكواه إلى الله: رب إن قومي كذّبون، فاحكم بيني وبينهم فأهلكهم، ونجّني ومن معي من المؤمنين. فأنجيناه ومن معه في السفينة المملوءة بأنواع الحيوانات، ثم أغرقنا بعد ذلك الباقين، إذ ظل الماء النازل من السماء والنابع من الأرض يرتفع حتى غرق كل من على الأرض. إن في ذلك الصراع بين التوحيد والشرك، وعاقبة أهل كلٍّ منهما، لعبرة، ولكن أهل مكة لم يعتبروا، وما كان أكثرهم مؤمنين، وإن ربك لهو العزيز الرحيم بمن تاب من عباده.", "h": ["بيان سنّة أن الظلمة والطغاة إذا أعيتهم الحجج يلجأون إلى القوة.", "جواز الاستنصار بالله تعالى، وطلب الفتح بين المظلوم والظالمين.", "سرعة استجابة الله تعالى لعبده نوح لصبره قروناً طويلة، فلما رفع شكواه إلى ربه أجابه فأنجاه وأهلك أعداءه."], "k": "«رب إن قومي كذّبون»… صبر نوح ﵇ قروناً قبل أن يشكو؛ فكم أصبر أنا قبل أن أستعجل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 263;
