insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (264, 26, 123, 140, 'سورة الشعراء ١٢٣ – ١٤٠', '«كذّبت عاد المرسلين»: «أتبنون بكل ريع آية تعبثون»، و«واتقوا الذي أمدّكم بما تعلمون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 264) = $j$[{"lbl": "الآيات ١٢٣ – ١٣١", "q": "كَذَّبَتۡ عَادٌ ٱلۡمُرۡسَلِينَ ﴿١٢٣﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ هُودٌ أَلَا تَتَّقُونَ ﴿١٢٤﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٢٥﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٢٦﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٢٧﴾ أَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ﴿١٢٨﴾ وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ ﴿١٢٩﴾ وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ ﴿١٣٠﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٣١﴾", "w": [["كذّبت عاد", "عاد اسم أبي القبيلة، وسُمّيت القبيلة به."], ["أخوهم هود", "أخوهم في النسب."], ["أتبنون بكل ريع", "بكل مكان عالٍ مرتفع."], ["آية", "قصراً مشيداً عالياً مرتفعاً."], ["تعبثون", "تبنون ما لا تسكنون."], ["وتتخذون مصانع", "حصوناً منيعة وقصوراً رفيعة."], ["لعلكم تخلدون", "كأنكم تأملون الخلود في الأرض."], ["وإذا بطشتم", "إذا أخذتم أحداً سطوتم عليه بعنف وشدة."], ["جبّارين", "عتاة متسلّطين."]], "m": "هذه بداية قصص هود ﵇: كذّبت عاد رسول الله هوداً، إذ قال لهم أخوهم: ألا تتقون عقاب الله بترك الشرك؟ إني لكم رسول أمين على ما أبلّغكم، لا أزيد ولا أنقص، فاتقوا الله وأطيعوني، وما أسألكم على إبلاغ رسالتي من أجر مهما قلّ، إن أجري إلا على رب العالمين الذي أرسلني. ثم أنكر عليهم انهماكهم في الدنيا وانشغالهم بما لا يعنيهم: أتبنون بكل مكان مرتفع قصراً مشيداً آية في علوّه، لا تسكنونه، لمجرد اللهو والعبث؟ وتتخذون مباني عالية كالحصون كأنكم تخلدون، وما أنتم بخالدين؟ وإذا سطوتم على أحد سطوتم سطو الجبابرة بعنف وشدة بلا رحمة؟ فاتقوا الله وأطيعوني، فإن ذلك خير لكم من التمادي في الباطل.", "h": ["الأمر بالتقوى من النصح للمأمور بها، لأن النجاة والفوز لا يتمّان للعبد إلا عليها.", "الرسل أمناء على ما يحملون وما يبلّغون الناس.", "حرمة أخذ الأجرة على بيان الشرع والدعوة إلى ذلك.", "ينبغي للعبد ألا يسرف فيبني ما لا يسكن ويدّخر ما لا يأكل.", "استنكار العنف والشدة في الأخذ وعند المؤاخذة."], "k": "«أتبنون بكل ريع آية تعبثون»… كم من جهدي يذهب في بناء لن أسكنه، وأنا أحسب أني باقٍ؟"}, {"lbl": "الآيات ١٣٢ – ١٤٠", "q": "وَٱتَّقُواْ ٱلَّذِيٓ أَمَدَّكُم بِمَا تَعۡلَمُونَ ﴿١٣٢﴾ أَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ ﴿١٣٣﴾ وَجَنَّـٰتٖ وَعُيُونٍ ﴿١٣٤﴾ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٣٥﴾ قَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ﴿١٣٦﴾ إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ ﴿١٣٧﴾ وَمَا نَحۡنُ بِمُعَذَّبِينَ ﴿١٣٨﴾ فَكَذَّبُوهُ فَأَهۡلَكۡنَٰهُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٣٩﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٤٠﴾", "w": [["أمدّكم", "أعطاكم منعماً عليكم."], ["بأنعام", "الإبل والبقر والغنم."], ["عذاب يوم عظيم", "يوم هلاكهم في الدنيا، ويوم بعثهم يوم القيامة."], ["سواء علينا", "مستوٍ عندنا وعظك وعدمه، فإنا لا نطيعك."], ["إن هذا إلا خلق الأولين", "ما هذا الذي نحن عليه إلا دأب الأولين وعادتهم، فنحن على طريقتهم."]], "m": "أمرهم هود بتقوى الله الذي أنعم عليهم بما يعلمون من النعم، فإن طاعة المنعم شكر له ومعصيته كفر لإنعامه: أمدّكم بأنعام من إبل وبقر وغنم، وبنين، وبساتين وعيون لسقيها وسقيكم، ثم قال في إشفاق: إني أخاف عليكم عذاب يوم عظيم إن أصررتم على الشرك. فكان ردّهم: سواء علينا أوعظت أم لم تكن من الواعظين، فما نحن بتاركي ما نحن عليه، إن هذا الذي نحن عليه من البناء وعبادة آلهتنا إلا عادة من سبقنا، وما نحن بمعذّبين عليه. فكذّبوه فأهلكناهم، إن في ذلك لعبرة لقومك لو كانوا يعتبرون، وما كان أكثرهم مؤمنين، وإن ربك لهو العزيز الذي أخذ الجبابرة العتاة، الرحيم بأوليائه فأنجاهم.", "h": ["تنويع أسلوب الدعوة، وتذكير الجاحدين بما هو محسوس لديهم مرئيّ لهم.", "التخويف من عذاب الله والتحذير من عاقبة عصيانه من أساليب الدعوة.", "بيان سنة الناس في التقليد واتباع آبائهم وإن كانوا ضُلّالاً جاهلين.", "تقرير التوحيد والنبوة والبعث، إذ هو المقصود من هذا القصص."], "k": "«واتقوا الذي أمدّكم بما تعلمون»… أعدّ النعم التي أعلمها الآن، ثم أسأل: هل شكرتها بالطاعة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 264;
insert into public.tdb_cards(topic, i, body) select 264, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢٣ – ١٣١", "q": "كَذَّبَتۡ عَادٌ ٱلۡمُرۡسَلِينَ ﴿١٢٣﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ هُودٌ أَلَا تَتَّقُونَ ﴿١٢٤﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٢٥﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٢٦﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٢٧﴾ أَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ ﴿١٢٨﴾ وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ ﴿١٢٩﴾ وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ ﴿١٣٠﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٣١﴾", "w": [["كذّبت عاد", "عاد اسم أبي القبيلة، وسُمّيت القبيلة به."], ["أخوهم هود", "أخوهم في النسب."], ["أتبنون بكل ريع", "بكل مكان عالٍ مرتفع."], ["آية", "قصراً مشيداً عالياً مرتفعاً."], ["تعبثون", "تبنون ما لا تسكنون."], ["وتتخذون مصانع", "حصوناً منيعة وقصوراً رفيعة."], ["لعلكم تخلدون", "كأنكم تأملون الخلود في الأرض."], ["وإذا بطشتم", "إذا أخذتم أحداً سطوتم عليه بعنف وشدة."], ["جبّارين", "عتاة متسلّطين."]], "m": "هذه بداية قصص هود ﵇: كذّبت عاد رسول الله هوداً، إذ قال لهم أخوهم: ألا تتقون عقاب الله بترك الشرك؟ إني لكم رسول أمين على ما أبلّغكم، لا أزيد ولا أنقص، فاتقوا الله وأطيعوني، وما أسألكم على إبلاغ رسالتي من أجر مهما قلّ، إن أجري إلا على رب العالمين الذي أرسلني. ثم أنكر عليهم انهماكهم في الدنيا وانشغالهم بما لا يعنيهم: أتبنون بكل مكان مرتفع قصراً مشيداً آية في علوّه، لا تسكنونه، لمجرد اللهو والعبث؟ وتتخذون مباني عالية كالحصون كأنكم تخلدون، وما أنتم بخالدين؟ وإذا سطوتم على أحد سطوتم سطو الجبابرة بعنف وشدة بلا رحمة؟ فاتقوا الله وأطيعوني، فإن ذلك خير لكم من التمادي في الباطل.", "h": ["الأمر بالتقوى من النصح للمأمور بها، لأن النجاة والفوز لا يتمّان للعبد إلا عليها.", "الرسل أمناء على ما يحملون وما يبلّغون الناس.", "حرمة أخذ الأجرة على بيان الشرع والدعوة إلى ذلك.", "ينبغي للعبد ألا يسرف فيبني ما لا يسكن ويدّخر ما لا يأكل.", "استنكار العنف والشدة في الأخذ وعند المؤاخذة."], "k": "«أتبنون بكل ريع آية تعبثون»… كم من جهدي يذهب في بناء لن أسكنه، وأنا أحسب أني باقٍ؟"}, {"lbl": "الآيات ١٣٢ – ١٤٠", "q": "وَٱتَّقُواْ ٱلَّذِيٓ أَمَدَّكُم بِمَا تَعۡلَمُونَ ﴿١٣٢﴾ أَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ ﴿١٣٣﴾ وَجَنَّـٰتٖ وَعُيُونٍ ﴿١٣٤﴾ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ﴿١٣٥﴾ قَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ ﴿١٣٦﴾ إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ ﴿١٣٧﴾ وَمَا نَحۡنُ بِمُعَذَّبِينَ ﴿١٣٨﴾ فَكَذَّبُوهُ فَأَهۡلَكۡنَٰهُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٣٩﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٤٠﴾", "w": [["أمدّكم", "أعطاكم منعماً عليكم."], ["بأنعام", "الإبل والبقر والغنم."], ["عذاب يوم عظيم", "يوم هلاكهم في الدنيا، ويوم بعثهم يوم القيامة."], ["سواء علينا", "مستوٍ عندنا وعظك وعدمه، فإنا لا نطيعك."], ["إن هذا إلا خلق الأولين", "ما هذا الذي نحن عليه إلا دأب الأولين وعادتهم، فنحن على طريقتهم."]], "m": "أمرهم هود بتقوى الله الذي أنعم عليهم بما يعلمون من النعم، فإن طاعة المنعم شكر له ومعصيته كفر لإنعامه: أمدّكم بأنعام من إبل وبقر وغنم، وبنين، وبساتين وعيون لسقيها وسقيكم، ثم قال في إشفاق: إني أخاف عليكم عذاب يوم عظيم إن أصررتم على الشرك. فكان ردّهم: سواء علينا أوعظت أم لم تكن من الواعظين، فما نحن بتاركي ما نحن عليه، إن هذا الذي نحن عليه من البناء وعبادة آلهتنا إلا عادة من سبقنا، وما نحن بمعذّبين عليه. فكذّبوه فأهلكناهم، إن في ذلك لعبرة لقومك لو كانوا يعتبرون، وما كان أكثرهم مؤمنين، وإن ربك لهو العزيز الذي أخذ الجبابرة العتاة، الرحيم بأوليائه فأنجاهم.", "h": ["تنويع أسلوب الدعوة، وتذكير الجاحدين بما هو محسوس لديهم مرئيّ لهم.", "التخويف من عذاب الله والتحذير من عاقبة عصيانه من أساليب الدعوة.", "بيان سنة الناس في التقليد واتباع آبائهم وإن كانوا ضُلّالاً جاهلين.", "تقرير التوحيد والنبوة والبعث، إذ هو المقصود من هذا القصص."], "k": "«واتقوا الذي أمدّكم بما تعلمون»… أعدّ النعم التي أعلمها الآن، ثم أسأل: هل شكرتها بالطاعة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (265, 26, 141, 159, 'سورة الشعراء ١٤١ – ١٥٩', '«كذّبت ثمود المرسلين»: «وتنحتون من الجبال بيوتاً فارهين»، و«هذه ناقة لها شرب ولكم شرب يوم معلوم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 265) = $j$[{"lbl": "الآيات ١٤١ – ١٥٢", "q": "كَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ ﴿١٤١﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ صَٰلِحٌ أَلَا تَتَّقُونَ ﴿١٤٢﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٤٣﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٤٤﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٤٥﴾ أَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ ﴿١٤٦﴾ فِي جَنَّـٰتٖ وَعُيُونٖ ﴿١٤٧﴾ وَزُرُوعٖ وَنَخۡلٖ طَلۡعُهَا هَضِيمٞ ﴿١٤٨﴾ وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ ﴿١٤٩﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٥٠﴾ وَلَا تُطِيعُوٓاْ أَمۡرَ ٱلۡمُسۡرِفِينَ ﴿١٥١﴾ ٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ ﴿١٥٢﴾", "w": [["كذّبت ثمود المرسلين", "كذّبت قبيلة ثمود نبيّها صالحاً."], ["فيما ها هنا آمنين", "من الخيرات والنعم، غير خائفين من أحد."], ["طلعها هضيم", "طلع النخل ليّن ناعم ما دام في غلافه."], ["وتنحتون من الجبال بيوتاً", "تنحتون الصخور في الجبال وتتخذون منها بيوتاً."], ["فارهين", "حاذقين من جهة، وبطرين متكبّرين مغترّين بصنيعكم من جهة."], ["المسرفين", "في الشر والفساد بالكفر والعناد."], ["الذين يفسدون في الأرض", "بارتكاب الذنوب العظام فيها."], ["ولا يصلحون", "بفعل الطاعات والقربات."]], "m": "هذه بداية قصص صالح ﵇: جحدت ثمود ما جاءها به رسولها صالح، إذ قال لهم أخوهم في النسب لا في الدين: ألا تتقون عذاب الله بالإيمان به وتوحيده؟ إني لكم رسول أمين على رسالة الله، فاتقوا الله وأطيعوني، وكرّر الأمر بهما إذ هما معظم رسالته، وما أسألكم عليه من أجر، فأبعد عن نفسه تهمة طلب المال. ثم ذكّرهم بالنعم: أتظنّون أنكم تُتركون فيما بين أيديكم من الخيرات آمنين، في بساتين ومزارع وعيون، ونخل طلعها ليّن ناعم، وتنحتون من الجبال الصمّ بيوتاً تسكنونها، حاذقين في فن النحت، بطرين مغترّين بقوتكم وصناعتكم؟ فاتقوا الله وأطيعوني، ولا تطيعوا أمر المسرفين بارتكاب الكبائر، الذين جمعوا بين الفساد والإفساد، وترك الصلاح والإصلاح.", "h": ["دعوة الرسل واحدة، ولذا يُعتبر التكذيب برسول تكذيباً بكل الرسل.", "الأمانة شعار كل الرسل والدعاة الصادقين في كل الأمم والعصور.", "مشروعية التذكير بالنعم ليُذكر المنعم فيُحبّ ويُطاع.", "التحذير من طاعة المسرفين في الذنوب والمعاصي لوخامة عاقبة طاعتهم.", "تقرير أن الفساد في الأرض يكون بارتكاب المعاصي فيها."], "k": "«أتُتركون فيما ها هنا آمنين»… هل أعيش في النعمة كأنها لن تزول، وكأني لن أُسأل عنها؟"}, {"lbl": "الآيات ١٥٣ – ١٥٩", "q": "قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ ﴿١٥٣﴾ مَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا فَأۡتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿١٥٤﴾ قَالَ هَٰذِهِۦ نَاقَةٞ لَّهَا شِرۡبٞ وَلَكُمۡ شِرۡبُ يَوۡمٖ مَّعۡلُومٖ ﴿١٥٥﴾ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابُ يَوۡمٍ عَظِيمٖ ﴿١٥٦﴾ فَعَقَرُوهَا فَأَصۡبَحُواْ نَٰدِمِينَ ﴿١٥٧﴾ فَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٥٨﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٥٩﴾", "w": [["إنما أنت من المسحّرين", "الذين سُحروا وبولغ في سحرهم حتى غلب على عقولهم."], ["فأت بآية", "تدل على صدقك إن كنت رسولاً."], ["لها شرب ولكم شرب يوم معلوم", "لها يوم تشرب فيه من العين، ولكم يوم آخر معلوم."], ["ولا تمسّوها بسوء", "لا بضرب ولا بقتل ولا بمنع من الشرب."], ["فعقروها فأصبحوا نادمين", "قتلوها فأصبحوا نادمين لما شاهدوا علامات العذاب."]], "m": "لما وعظهم صالح ردّوا عليه: إنما أنت من الذين سُحروا حتى غلب السحر على عقولهم، ما أنت إلا بشر مثلنا، لا ربّ ولا ملك فنخضع لك، فأت بعلامة قوية على أنك رسول الله إن كنت من الصادقين. فسأل ربه آية فأعطاه ناقة عظيمة الخلق خرجت من الجبل وهم يشاهدون، فقال: هذه ناقة لها حظّ من ماء البلد تشربه وحدها، ولكم يوم معلوم تردونه وحدكم، ولا تمسّوها بسوء فيأخذكم عذاب يوم عظيم. فكذّبوه وعصوه وعقروها فقتلوها، فقال لهم صالح: تمتّعوا في داركم ثلاثة أيام، ذلك وعد غير مكذوب. فأصبحوا نادمين، وفي صبيحة اليوم الثالث أخذتهم الصيحة فأُهلكوا أجمعين، ونجّى الله صالحاً ومن معه من المؤمنين. إن في ذلك لعلامة كبرى على قدرة الله، وما كان أكثرهم مؤمنين مع وضوح الأدلة، وإن ربك لهو العزيز الرحيم بأوليائه.", "h": ["تقرير أن السحر من عمل الناس، وأنه معلوم لهم معمول به منذ القدم.", "سنّة الناس في المطالبة بالآيات عند دعوتهم إلى الدين الحق.", "وجود الآيات لا يستلزم بالضرورة إيمان المطالبين بها، بل أكثرهم لا يؤمنون.", "الندم من التوبة، ولكن لا ينفع ندم ولا توبة عند معاينة العذاب أو أماراته."], "k": "«فأصبحوا نادمين»… ندم بعد فوات الأوان؛ فما الذي أؤجّل التوبة منه الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 265;
insert into public.tdb_cards(topic, i, body) select 265, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٤١ – ١٥٢", "q": "كَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ ﴿١٤١﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ صَٰلِحٌ أَلَا تَتَّقُونَ ﴿١٤٢﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٤٣﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٤٤﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٤٥﴾ أَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ ﴿١٤٦﴾ فِي جَنَّـٰتٖ وَعُيُونٖ ﴿١٤٧﴾ وَزُرُوعٖ وَنَخۡلٖ طَلۡعُهَا هَضِيمٞ ﴿١٤٨﴾ وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ ﴿١٤٩﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٥٠﴾ وَلَا تُطِيعُوٓاْ أَمۡرَ ٱلۡمُسۡرِفِينَ ﴿١٥١﴾ ٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ ﴿١٥٢﴾", "w": [["كذّبت ثمود المرسلين", "كذّبت قبيلة ثمود نبيّها صالحاً."], ["فيما ها هنا آمنين", "من الخيرات والنعم، غير خائفين من أحد."], ["طلعها هضيم", "طلع النخل ليّن ناعم ما دام في غلافه."], ["وتنحتون من الجبال بيوتاً", "تنحتون الصخور في الجبال وتتخذون منها بيوتاً."], ["فارهين", "حاذقين من جهة، وبطرين متكبّرين مغترّين بصنيعكم من جهة."], ["المسرفين", "في الشر والفساد بالكفر والعناد."], ["الذين يفسدون في الأرض", "بارتكاب الذنوب العظام فيها."], ["ولا يصلحون", "بفعل الطاعات والقربات."]], "m": "هذه بداية قصص صالح ﵇: جحدت ثمود ما جاءها به رسولها صالح، إذ قال لهم أخوهم في النسب لا في الدين: ألا تتقون عذاب الله بالإيمان به وتوحيده؟ إني لكم رسول أمين على رسالة الله، فاتقوا الله وأطيعوني، وكرّر الأمر بهما إذ هما معظم رسالته، وما أسألكم عليه من أجر، فأبعد عن نفسه تهمة طلب المال. ثم ذكّرهم بالنعم: أتظنّون أنكم تُتركون فيما بين أيديكم من الخيرات آمنين، في بساتين ومزارع وعيون، ونخل طلعها ليّن ناعم، وتنحتون من الجبال الصمّ بيوتاً تسكنونها، حاذقين في فن النحت، بطرين مغترّين بقوتكم وصناعتكم؟ فاتقوا الله وأطيعوني، ولا تطيعوا أمر المسرفين بارتكاب الكبائر، الذين جمعوا بين الفساد والإفساد، وترك الصلاح والإصلاح.", "h": ["دعوة الرسل واحدة، ولذا يُعتبر التكذيب برسول تكذيباً بكل الرسل.", "الأمانة شعار كل الرسل والدعاة الصادقين في كل الأمم والعصور.", "مشروعية التذكير بالنعم ليُذكر