insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (266, 26, 160, 175, 'سورة الشعراء ١٦٠ – ١٧٥', '«كذّبت قوم لوط المرسلين»: «أتأتون الذكران من العالمين»، و«ربّ نجّني وأهلي مما يعملون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 266) = $j$[{"lbl": "الآيات ١٦٠ – ١٦٦", "q": "كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ ﴿١٦٠﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ ﴿١٦١﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٦٢﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٦٣﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٦٤﴾ أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ ﴿١٦٥﴾ وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ ﴿١٦٦﴾", "w": [["قوم لوط", "سكان سدوم وعمورية وقرى أخرى، ولوط ﵇ ابن أخي إبراهيم ﵇."], ["أخوهم لوط", "أخوّة بلد وسكنى، لا أخوّة نسب ولا دين."], ["إني لكم رسول أمين", "مرسل إليكم، أمين في إبلاغكم رسالتي فلا أنقص ولا أزيد."], ["فاتقوا الله", "بالإيمان به وعبادته وحده وترك معاصيه."], ["وما أسألكم عليه", "على البلاغ من أجرة مقابل إرشادكم وتعليمكم."], ["أتأتون الذكران من العالمين", "أتأتون الفاحشة من الرجال وتتركون النساء؟"], ["بل أنتم قوم عادون", "معتدون ظالمون متجاوزون الحد."]], "m": "هذه بداية قصص لوط ﵇ مع قومه: كذّبوا لوطاً، وتكذيبه تكذيب لكافة الرسل لأن دعوة الله واحدة، كذّبوه لما دعاهم إلى عبادة الله وحده وترك الفواحش والظلم، إذ قال لهم أخوهم لوط، وهي أخوّة الموطن لا غير، إذ أُرسل إليهم وسكن معهم: ألا تتقون الله؟ خاف عليهم الهلاك لقيامهم على عظائم الذنوب، فدعاهم إلى أسباب النجاة بطاعة الله وترك معاصيه، وقال: إني لكم رسول أمين فأطيعوني، ولا أسألكم أجراً على تبليغ رسالتي. ثم أنكر عليهم أعظم منكر موبّخاً: أتأتون الذكران من الناس، وتتركون ما خلق الله لكم من أزواجكم؟ بل أنتم قوم متجاوزون الحدود التي رسمها الشرع والعقل والآدمية.", "h": ["جواز إطلاق أخوّة الوطن دون الدين والنسب.", "الأمانة من مستلزمات الرسالة، إذ كل رسول يقول: «إني لكم رسول أمين».", "سبيل نجاة الفرد والجماعة في تقوى الله تعالى وطاعة الرسول.", "وجوب إنكار المنكر وتقبيحه على فاعله لعله يرعوي.", "أكبر فاحشة وقعت في الأرض هي فاحشة اللواط، والعياذ بالله تعالى."], "k": "«ألا تتقون»… دعاهم لوط ﵇ إلى أسباب النجاة وهم في أشدّ الفساد؛ فهل أيأس ممن حولي سريعاً؟"}, {"lbl": "الآيات ١٦٧ – ١٧٥", "q": "قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ ﴿١٦٧﴾ قَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ ﴿١٦٨﴾ رَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ ﴿١٦٩﴾ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ ﴿١٧٠﴾ إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ ﴿١٧١﴾ ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ ﴿١٧٢﴾ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ ﴿١٧٣﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٧٤﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٧٥﴾", "w": [["لئن لم تنته", "عن إنكارك علينا ما نأتيه من الفاحشة."], ["من المخرجين", "من بلادنا، مطروداً من ديارنا."], ["من القالين", "المبغضين أشد البغض."], ["رب نجّني وأهلي مما يعملون", "من عقوبة ما يعملونه من الفواحش."], ["إلا عجوزاً في الغابرين", "امرأته الكافرة الراضية بعملهم، تُركت معهم حتى هلكت."], ["وأمطرنا عليهم مطراً", "حجارة من السماء بعد قلب البلاد عاليها سافلها."], ["فساء مطر المنذرين", "قبح مطر المنذَرين الذين لم يكفّوا عن الشر."]], "m": "لما وعظهم لوط أجابوا: لئن لم تنته يا لوط عن إنكارك علينا لنخرجنّك من بلادنا. فأجابهم: إني لعملكم من المبغضين أشد البغض. ثم التفت إلى ربه ضارعاً، بعد أن أقام يدعوهم سنين عديدة: رب نجّني وأهلي من عقوبة ما يعملون. فنجّيناه وأهله، امرأته المسلمة وابنتيه، إلا عجوزاً، امرأته الكافرة الراضية بالفعلة الشنعاء، كانت في جملة المتروكين لتهلك مع الهالكين. ثم أهلكنا الآخرين، وبعد قلب البلاد أمطرنا عليهم حجارة من السماء تصيب من كان خارج المدن المقلوبة، فقبح مطر المنذَرين. إن في ذلك لعلامة كبرى لمن يسمع ويرى، وما كان أكثرهم مؤمنين، وإن ربك لهو العزيز القاهر للظلمة، الرحيم بأوليائه.", "h": ["وجوب بغض الشر والفساد في أي صورة من صورهما.", "استجابة دعوة المظلوم، لا سيما إن كان من الصالحين.", "توقّع العذاب إذا انتشر الشر وعظم الظلم والفساد.", "الآيات مهما كانت عظيمة لا تستلزم الإيمان والطاعة.", "مظاهر قدرة الله وعلمه ورحمته."], "k": "«إني لعملكم من القالين»… أبغض الفعل لا أن أستأنس به؛ فهل بقي في قلبي هذا البغض للمنكر، أم ألِفته؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 266;
insert into public.tdb_cards(topic, i, body) select 266, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦٠ – ١٦٦", "q": "كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ ﴿١٦٠﴾ إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ ﴿١٦١﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٦٢﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٦٣﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٦٤﴾ أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ ﴿١٦٥﴾ وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ ﴿١٦٦﴾", "w": [["قوم لوط", "سكان سدوم وعمورية وقرى أخرى، ولوط ﵇ ابن أخي إبراهيم ﵇."], ["أخوهم لوط", "أخوّة بلد وسكنى، لا أخوّة نسب ولا دين."], ["إني لكم رسول أمين", "مرسل إليكم، أمين في إبلاغكم رسالتي فلا أنقص ولا أزيد."], ["فاتقوا الله", "بالإيمان به وعبادته وحده وترك معاصيه."], ["وما أسألكم عليه", "على البلاغ من أجرة مقابل إرشادكم وتعليمكم."], ["أتأتون الذكران من العالمين", "أتأتون الفاحشة من الرجال وتتركون النساء؟"], ["بل أنتم قوم عادون", "معتدون ظالمون متجاوزون الحد."]], "m": "هذه بداية قصص لوط ﵇ مع قومه: كذّبوا لوطاً، وتكذيبه تكذيب لكافة الرسل لأن دعوة الله واحدة، كذّبوه لما دعاهم إلى عبادة الله وحده وترك الفواحش والظلم، إذ قال لهم أخوهم لوط، وهي أخوّة الموطن لا غير، إذ أُرسل إليهم وسكن معهم: ألا تتقون الله؟ خاف عليهم الهلاك لقيامهم على عظائم الذنوب، فدعاهم إلى أسباب النجاة بطاعة الله وترك معاصيه، وقال: إني لكم رسول أمين فأطيعوني، ولا أسألكم أجراً على تبليغ رسالتي. ثم أنكر عليهم أعظم منكر موبّخاً: أتأتون الذكران من الناس، وتتركون ما خلق الله لكم من أزواجكم؟ بل أنتم قوم متجاوزون الحدود التي رسمها الشرع والعقل والآدمية.", "h": ["جواز إطلاق أخوّة الوطن دون الدين والنسب.", "الأمانة من مستلزمات الرسالة، إذ كل رسول يقول: «إني لكم رسول أمين».", "سبيل نجاة الفرد والجماعة في تقوى الله تعالى وطاعة الرسول.", "وجوب إنكار المنكر وتقبيحه على فاعله لعله يرعوي.", "أكبر فاحشة وقعت في الأرض هي فاحشة اللواط، والعياذ بالله تعالى."], "k": "«ألا تتقون»… دعاهم لوط ﵇ إلى أسباب النجاة وهم في أشدّ الفساد؛ فهل أيأس ممن حولي سريعاً؟"}, {"lbl": "الآيات ١٦