insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (267, 26, 176, 191, 'سورة الشعراء ١٧٦ – ١٩١', '«كذّب أصحاب الأيكة المرسلين»: «أوفوا الكيل ولا تكونوا من المخسرين»، و«فأخذهم عذاب يوم الظلّة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 267) = $j$[{"lbl": "الآيات ١٧٦ – ١٨٤", "q": "كَذَّبَ أَصۡحَٰبُ لۡـَٔيۡكَةِ ٱلۡمُرۡسَلِينَ ﴿١٧٦﴾ إِذۡ قَالَ لَهُمۡ شُعَيۡبٌ أَلَا تَتَّقُونَ ﴿١٧٧﴾ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٧٨﴾ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿١٧٩﴾ وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٨٠﴾ ۞أَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ ﴿١٨١﴾ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ ﴿١٨٢﴾ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿١٨٣﴾ وَٱتَّقُواْ ٱلَّذِي خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِينَ ﴿١٨٤﴾", "w": [["أصحاب الأيكة", "الغيضة، وهي الشجر الملتفّ."], ["إذ قال لهم شعيب", "النبي المرسل شعيب ﵇."], ["أوفوا الكيل", "أتمّوه ولا تنقصوه."], ["ولا تكونوا من المخسرين", "الذين ينقصون الكيل والوزن."], ["بالقسطاس المستقيم", "الميزان السويّ المعتدل."], ["ولا تبخسوا الناس أشياءهم", "لا تنقصوهم من حقوقهم شيئاً."], ["ولا تعثوا في الأرض مفسدين", "بالقتل والسلب والنهب."], ["والجبلّة الأولين", "الخليقة، أي الناس من قبلكم."]], "m": "هذه بداية قصص شعيب ﵇ مع أصحاب الأيكة، والأيكة شجر ملتفّ قريب من مدين، وقد أُرسل شعيب إلى أهلهما معاً، فقيل في سورة هود: «وإلى مدين أخاهم شعيباً» لأنه منهم، وأما أصحاب الأيكة فجماعة من بادية مدين كانت لهم أيكة يعبدونها. فدعاهم إلى عبادة الله وحده فكذّبوه، إذ قال لهم: ألا تتقون الله وتخافون عقابه؟ إني لكم رسول أمين، فاتقوا الله وأطيعوني أهدكم إلى ما فيه كمالكم، وما أسألكم على بلاغ رسالة ربي أجراً. ثم أمرهم بترك أشهر معصية شائعة بينهم، وهي تطفيف الكيل والوزن: أتمّوا الكيل ولا تكونوا من الذين ينقصونه، وإذا وزنتم فزنوا بالميزان العادل، ولا تنقصوا الناس حقوقهم، فما يساوي ديناراً لا تعطوا فيه نصفه، ومن أجرته اليومية عشرون لا تعطوه عشرة، ولا تفسدوا في البلاد بأي نوع من الفساد، واتقوا الذي خلقكم وخلق الخليقة من قبلكم.", "h": ["الأمر بالتقوى فريضة كل داعٍ إلى الله تعالى، وسنّة الدعاة والهداة.", "لا يصحّ لداعٍ إلى الله أن يطلب أجره ممن يدعوهم، فإن ذلك ينفّرهم.", "وجوب توفية الكيل والوزن، وحرمة التطفيف فيهما.", "حرمة بخس الناس حقوقهم ونقصها بأي حال من الأحوال.", "حرمة الفساد في الأرض بارتكاب المعاصي وغشيان الذنوب."], "k": "«ولا تبخسوا الناس أشياءهم»… في أجر عامل، أو ثمن سلعة، أو حتى في كلمة إنصاف؛ أين أبخس دون أن أنتبه؟"}, {"lbl": "الآيات ١٨٥ – ١٩١", "q": "قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ ﴿١٨٥﴾ وَمَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلۡكَٰذِبِينَ ﴿١٨٦﴾ فَأَسۡقِطۡ عَلَيۡنَا كِسَفٗا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿١٨٧﴾ قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ ﴿١٨٨﴾ فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ يَوۡمٍ عَظِيمٍ ﴿١٨٩﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ ﴿١٩٠﴾ وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿١٩١﴾", "w": [["إنما أنت من المسحّرين", "ممن غلب السحر على عقولهم."], ["وإن نظنّك لمن الكاذبين", "وما نحسبك إلا واحداً من الكاذبين."], ["فأسقط علينا كسفاً", "قطعاً من السماء تهلكنا بها."], ["عذاب يوم الظلّة", "السحابة التي أظلّتهم ثم التهبت عليهم ناراً."], ["إن في ذلك لآية", "لعبرة لمن يعتبر."]], "m": "لما وعظهم شعيب كان جوابهم: إنما أنت ممن غلب السحر على عقولهم، وما أنت إلا بشر مثلنا تأكل وتشرب، لست بملك حتى نطيعك، وما نظنك إلا من الكاذبين، فأسقط علينا قطعاً من السماء تهلكنا إن كنت صادقاً في دعوى الرسالة. فأجابهم: ربي أعلم بما تعملون، ولازم ذلك أنه سيجازيكم. فكذّبوه فاستوجبوا العذاب، فأخذهم عذاب يوم الظلّة: أنزل الله عليهم حرّاً شديداً فلجأوا إلى المنازل والكهوف والسراديب فلم تغن عنهم شيئاً، ثم ارتفعت في سماء بلادهم سحابة فوجد من ذهب إليها تحتها برداً وطيباً، فنادى الناس فاجتمعوا تحتها، فانقلبت ناراً فأحرقتهم، ورجفت بهم الأرض فهلكوا عن آخرهم. إن في ذلك لعلامة لقومك على قدرتنا ووجوب عبادتنا، وما كان أكثرهم مؤمنين، وإن ربك لهو العزيز الرحيم بمن تاب.", "h": ["هذا آخر سبع قصص ذُكرت بإيجاز تسلية للنبي ﷺ وتهديداً للمشركين المكذّبين.", "دعوة الرسل واحدة، وأسلوبهم يكاد يكون واحداً: الأمر بتقوى الله وطاعة رسوله.", "سنّة تعلّل الناس بأن الرسول لا ينبغي أن يكون بشراً، فلذا هم لا يؤمنون.", "المطالبة بالآيات تكاد تكون سنّة مطّردة، وقلّ من يؤمن عليها.", "تقرير التوحيد والنبوة والبعث، وهي ثمرة كل قصة تُقصّ في هذا القرآن العظيم."], "k": "«ربي أعلم بما تعملون»… كلمة تكفي لمن يتذكّر أن الله يرى؛ فهل تكفيني أنا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 267;
