insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (268, 26, 192, 212, 'سورة الشعراء ١٩٢ – ٢١٢', '«وإنه لتنزيل رب العالمين، نزل به الروح الأمين على قلبك»، و«وما تنزّلت به الشياطين»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 268) = $j$[{"lbl": "الآيات ١٩٢ – ٢٠٣", "q": "وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٩٢﴾ نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ ﴿١٩٣﴾ عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ ﴿١٩٤﴾ بِلِسَانٍ عَرَبِيّٖ مُّبِينٖ ﴿١٩٥﴾ وَإِنَّهُۥ لَفِي زُبُرِ ٱلۡأَوَّلِينَ ﴿١٩٦﴾ أَوَلَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ عُلَمَـٰٓؤُاْ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٩٧﴾ وَلَوۡ نَزَّلۡنَٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِينَ ﴿١٩٨﴾ فَقَرَأَهُۥ عَلَيۡهِم مَّا كَانُواْ بِهِۦ مُؤۡمِنِينَ ﴿١٩٩﴾ كَذَٰلِكَ سَلَكۡنَٰهُ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ ﴿٢٠٠﴾ لَا يُؤۡمِنُونَ بِهِۦ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٢٠١﴾ فَيَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٢٠٢﴾ فَيَقُولُواْ هَلۡ نَحۡنُ مُنظَرُونَ ﴿٢٠٣﴾", "w": [["وإنه لتنزيل رب العالمين", "القرآن الكريم تنزيل رب العالمين."], ["الروح الأمين", "جبريل ﵇، أمين على وحي الله تعالى."], ["وإنه لفي زبر الأولين", "في كتب الأولين."], ["أوَلم يكن لهم آية", "علامة ودليلاً على صدقه."], ["أن يعلمه علماء بني إسرائيل", "علم علماء بني إسرائيل به."], ["على بعض الأعجمين", "الأعجمي: من لا يقدر على التكلّم بالعربية."], ["كذلك سلكناه", "أدخلنا التكذيب في قلوب المجرمين من كفار مكة."]], "m": "أنكر كفار مكة أن يكون القرآن وحياً، فأنكروا رسالة محمد ﷺ، وإيراد هذا القصص يتلوه وهو لا يقرأ ولا يكتب دليل قاطع على أنه وحي. وإن القرآن لتنزيل رب العالمين، نزل به جبريل الأمين على قلبك، لأن القلب محطّ الإدراك والوعي والحفظ، لتكون من المنذرين، بلسان عربي مبين. وإنه لمذكور في الكتب الإلهية السابقة كالتوراة والإنجيل. أوَلم يكن لقريش علامة على أنه وحي الله أن يعلمه علماء بني إسرائيل، كعبد الله بن سلام؟ ومن عرف محمداً رسولاً عرف القرآن وحياً. ولو نزّلناه على بعض الأعجمين فقرأه عليهم ما كانوا به مؤمنين، أنفة وحميّة. كذلك أدخلنا التكذيب في قلوب المجرمين، لأن الإجرام على النفس بعظائم الذنوب يحول بينها وبين قبول الحق لما ران عليها، فلا يؤمنون به حتى يروا العذاب الأليم، فيأتيهم فجأة وهم لا يشعرون، فيقولون: هل نحن ممهلون؟", "h": ["تقرير معتقد الوحي الإلهي والنبوة المحمدية.", "بيان أن جبريل هو الذي كان ينزل بالوحي القرآني على النبي محمد ﷺ.", "تقرير النبوة المحمدية، وأن محمداً ﷺ من المنذرين.", "بيان أن القرآن مذكور في الكتب السابقة بشهادة علماء أهل الكتاب.", "إذا تراكمت آثار الذنوب والجرائم على النفس حجبتها عن التوبة ومنعتها من الإيمان."], "k": "«على قلبك»… نزل القرآن على القلب قبل اللسان؛ فهل يبلغ ما أتلوه قلبي، أم يقف عند لساني؟"}, {"lbl": "الآيات ٢٠٤ – ٢١٢", "q": "أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ ﴿٢٠٤﴾ أَفَرَءَيۡتَ إِن مَّتَّعۡنَٰهُمۡ سِنِينَ ﴿٢٠٥﴾ ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ ﴿٢٠٦﴾ مَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ ﴿٢٠٧﴾ وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا لَهَا مُنذِرُونَ ﴿٢٠٨﴾ ذِكۡرَىٰ وَمَا كُنَّا ظَٰلِمِينَ ﴿٢٠٩﴾ وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّيَٰطِينُ ﴿٢١٠﴾ وَمَا يَنۢبَغِي لَهُمۡ وَمَا يَسۡتَطِيعُونَ ﴿٢١١﴾ إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ ﴿٢١٢﴾", "w": [["هل نحن منظرون", "ممهلون لنؤمن؟ والجواب قطعاً: لا."], ["أفرأيت", "أخبرني."], ["إن متّعناهم سنين", "أبقينا على حياتهم يأكلون ويشربون وينكحون."], ["ما كانوا يوعدون", "من العذاب."], ["ما أغنى عنهم", "أيّ شيء أغنى عنهم ذلك التمتّع الطويل؟"], ["إلا لها منذرون", "رسل ينذرون أهلها عاقبة الكفر والشرك."], ["ذكرى", "عظة."], ["وما تنزّلت به الشياطين", "لا يتأتّى لهم ولا يصلح أن يتنزّلوا به."], ["إنهم عن السمع لمعزولون", "عن سماع كلام الملائكة."]], "m": "أفبعذابنا يستعجلون حين قالوا: لن نؤمن لك حتى تُسقط علينا قطعاً من السماء؟ أحمقى هم يستعجلون عذاباً إن جاءهم كان فيه حتفهم؟ أخبرني يا رسولنا: إن أطلنا أعمارهم ووسّعنا أرزاقهم سنين، ثم جاءهم عذابنا، هل يغني عنهم ذلك التمتّع شيئاً؟ لا، لا بدفع العذاب ولا بتأخيره ولا بتخفيفه. وما أهلكنا من قرية كتلك القرى التي مرّ ذكرها إلا لها رسل ينذرون أهلها، عظة لعلهم يتّعظون، وما كنا ظالمين في إهلاك من أهلكنا بعد الإنذار. ونزل ردّاً على المشركين الذين زعموا أن الشياطين تلقي القرآن على لسان محمد كما تأتي الكهّان بأخبار السماء: وما تنزّلت به الشياطين، وما يصلح لهم ولا يقدرون عليه، لأنهم معزولون عن سماع كلام الملائكة، إذ أرصد الله لهم شهباً حالت بينهم وبين السماع.", "h": ["بيان أن المجرمين إذا شاهدوا العذاب تمنّوا التوبة ولا يُمكَّنون منها.", "بيان أن استعجال عذاب الله حمق وفساد في الرأي والعقل.", "بيان أن طول العمر وسعة الرزق لا يغنيان عن صاحبهما شيئاً من عذاب الله إذا نزل به.", "بيان سنّة الله تعالى في أنه لا يُهلك أمة إلا بعد الإنذار والبيان.", "إبطال مزاعم المشركين في أن القرآن من جنس ما يقوله الكهّان."], "k": "«ما أغنى عنهم ما كانوا يمتّعون»… سنوات من المتعة لا تدفع ساعة عذاب؛ فبأي شيء أقيس أيامي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 268;
insert into public.tdb_cards(topic, i, body) select 268, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٩٢ – ٢٠٣", "q": "وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ ﴿١٩٢﴾ نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ ﴿١٩٣﴾ عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ ﴿١٩٤﴾ بِلِسَانٍ عَرَبِيّٖ مُّبِينٖ ﴿١٩٥﴾ وَإِنَّهُۥ لَفِي زُبُرِ ٱلۡأَوَّلِينَ ﴿١٩٦﴾ أَوَلَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ عُلَمَـٰٓؤُاْ بَنِيٓ إِسۡرَـٰٓءِيلَ ﴿١٩٧﴾ وَلَوۡ نَزَّلۡنَٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِينَ ﴿١٩٨﴾ فَقَرَأَهُۥ عَلَيۡهِم مَّا كَانُواْ بِهِۦ مُؤۡمِنِينَ ﴿١٩٩﴾ كَذَٰلِكَ سَلَكۡنَٰهُ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ ﴿٢٠٠﴾ لَا يُؤۡمِنُونَ بِهِۦ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ﴿٢٠١﴾ فَيَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ﴿٢٠٢﴾ فَيَقُولُواْ هَلۡ نَحۡنُ مُنظَرُونَ ﴿٢٠٣﴾", "w": [["وإنه لتنزيل رب العالمين", "القرآن الكريم تنزيل رب العالمين."], ["الروح الأمين", "جبريل ﵇، أمين على وحي الله تعالى."], ["وإنه لفي زبر الأولين", "في كتب الأولين."], ["أوَلم يكن لهم آية", "علامة ودليلاً على صدقه."], ["أن يعلمه علماء بني إسرائيل", "علم علماء بني إسرائيل به."], ["على بعض الأعجمين", "الأعجمي: من لا يقدر على التكلّم بالعربية."], ["كذلك سلكناه", "أدخلنا التكذيب في قلوب المجرمين من كفار مكة."]], "m": "أنكر كفار مكة أن يكون القرآن وحياً، فأنكروا رسالة محمد ﷺ، وإيراد هذا القصص يتلوه وهو لا يقرأ ولا يكتب دليل قاطع على أنه وحي. وإن القرآن لتنزيل رب العالمين، نزل به جبريل الأمين على قلبك، لأن القلب محطّ الإدراك والوعي والحفظ، لتكون من المنذرين، بلسان عربي مبين. وإنه لمذكور في الكتب الإلهية السابقة كالتوراة والإنجيل. أوَلم يكن لقريش علامة على أنه وحي الله أن يعلمه علماء بني إسرائيل، كعبد الله بن سلام؟ ومن عرف محمداً رسولاً عرف القرآن وحياً. ولو نزّلناه على بعض الأعجمين فقرأه عليهم ما كانوا به مؤمنين، أنفة وحميّة. كذلك أدخلنا التكذيب في قلوب المجرمين، لأن الإجرام على النفس بعظائم الذنوب يحول بينها وبين قبول الحق لما ران عليها، فلا يؤمنون به حتى يروا العذاب الأليم، فيأتيهم فجأة وهم لا يشعرون، فيقولون: هل نحن ممهلون؟", "h": ["تقرير معتقد الوحي الإلهي والنبوة المحمدية.", "بيان أن جبريل هو الذي كان ينزل بالوحي القرآني على النبي محمد ﷺ.", "تقرير النبوة المحمدية، وأن محمداً ﷺ من المنذرين.", "بيان أن القرآن مذكور في الكتب السابقة بشهادة علماء أهل الكتاب.", "إذا تراكمت آثار الذنوب والجرائم على النفس حجبتها عن التوبة ومنعتها من الإيمان."], "k": "«على قلبك»… نزل القرآن على القلب قبل اللسان؛ فهل يبلغ ما أتلوه قلبي، أم يقف عند لساني؟"}, {"lbl": "الآيات ٢٠٤ – ٢١٢", "q": "أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ ﴿٢٠٤﴾ أَفَرَءَيۡتَ إِن مَّتَّعۡنَٰهُمۡ سِنِينَ ﴿٢٠٥﴾ ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ ﴿٢٠٦﴾ مَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ ﴿٢٠٧﴾ وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا لَهَا مُنذِرُونَ ﴿٢٠٨﴾ ذِكۡرَىٰ وَمَا كُنَّا ظَٰلِمِينَ ﴿٢٠٩﴾ وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّيَٰطِينُ ﴿٢١٠﴾ وَمَا يَنۢبَغِي لَهُمۡ وَمَا يَسۡتَطِيعُونَ ﴿٢١١﴾ إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ ﴿٢١٢﴾", "w": [["هل نحن منظرون", "ممهلون لنؤمن؟ والجواب قطعاً: لا."], ["أفرأيت", "أخبرني."], ["إن متّعناهم سنين", "أبقينا على حياتهم يأكلون ويشربون وينكحون."], ["ما كانوا يوعدون", "من العذاب."], ["ما أغنى عنهم", "أيّ شيء أغنى عنهم ذلك التمتّع الطويل؟"], ["إلا لها منذرون", "رسل ينذرون أهلها عاقبة الكفر والشرك."], ["ذكرى", "عظة."], ["وما تنزّلت به الشياطين", "لا يتأتّى لهم ولا يصلح أن يتنزّلوا به."], ["إنهم عن السمع لمعزولون", "عن سماع كلام الملائكة."]], "m": "أفبعذابنا يستعجلون حين قالوا: لن نؤمن لك حتى تُسقط علينا قطعاً من السماء؟ أحمقى هم يستعجلون عذاباً إن جاءهم كان فيه حتفهم؟ أخبرني يا رسولنا: إن أطلنا أعمارهم ووسّعنا أرزاقهم سنين، ثم جاءهم عذابنا، هل يغني عنهم ذلك التمتّع شيئاً؟ لا، لا بدفع العذاب ولا بتأخيره ولا بتخفيفه. وما أهلكنا من قرية كتلك القرى التي مرّ ذكرها إلا لها رسل ينذرون أهلها، عظة لعلهم يتّعظون، وما كنا ظالمين في إهلاك من أهلكنا بعد الإنذار. ونزل ردّاً على المشركين الذين زعموا أن الشياطين تلقي القرآن على لسان محمد كما تأتي الكهّان بأخبار السماء: وما تنزّلت به الشياطين، وما يصلح لهم ولا يقدرون عليه، لأنهم معزولون عن سماع كلام الملائكة، إذ أرصد الله لهم شهباً حالت بينهم وبين السماع.", "h": ["بيان أن المجرمين إذا شاهدوا العذاب تمنّوا التوبة ولا يُمكَّنون منها.", "بيان أن استعجا