insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (269, 26, 213, 227, 'سورة الشعراء ٢١٣ – ٢٢٧', '«وأنذر عشيرتك الأقربين، واخفض جناحك»، و«الذي يراك حين تقوم»، و«والشعراء يتّبعهم الغاوون»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 269) = $j$[{"lbl": "الآيات ٢١٣ – ٢٢٠", "q": "فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ ﴿٢١٣﴾ وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ ﴿٢١٤﴾ وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٢١٥﴾ فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ ﴿٢١٦﴾ وَتَوَكَّلۡ عَلَى ٱلۡعَزِيزِ ٱلرَّحِيمِ ﴿٢١٧﴾ ٱلَّذِي يَرَىٰكَ حِينَ تَقُومُ ﴿٢١٨﴾ وَتَقَلُّبَكَ فِي ٱلسَّـٰجِدِينَ ﴿٢١٩﴾ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٢٢٠﴾", "w": [["فلا تدع مع الله إلهاً آخر", "لا تعبد مع الله إلهاً آخر، لأن الدعاء هو العبادة."], ["وأنذر عشيرتك الأقربين", "وهم بنو هاشم وبنو عبد المطلب."], ["واخفض جناحك", "ألِن جانبك."], ["فإن عصوك", "أبوا قبول دعوتك إلى التوحيد."], ["فقل إني بريء مما تعملون", "من عبادة غير الله سبحانه."], ["الذي يراك حين تقوم", "إلى الصلاة فتصلي متهجّداً بالليل وحدك."], ["وتقلّبك في الساجدين", "ويرى تقلّبك مع المصلين راكعاً ساجداً قائماً."]], "m": "ما زال السياق في طلب هداية قريش: فلا تعبد مع الله إلهاً آخر فتكون من المعذّبين، وفيه تعريض بالمشركين، إذ إن كان الرسول يُنهى عن ذلك ويُتوعّد فغيره أولى. وأنذر عشيرتك الأقربين، أمره أن يخصّ قرابته بالإنذار أولاً لأنهم أولى بطلب النجاة لهم، وقد امتثل فنادى بطون قريش واحداً واحداً: لا أغني عنكم من الله شيئاً، حتى قال: يا فاطمة بنت محمد، سليني من مالي ما شئت، لا أغني عنك من الله شيئاً. وألِن جانبك للمؤمنين واعطف عليهم ليرسخ الإيمان في قلوبهم وهم في بداية الطريق، فإن عصاك من أُمرت بدعوتهم فقل: إني بريء من عبادتكم غير الله. وتوكّل على العزيز الرحيم، إذ البراءة من الشرك وأهله تقتضي عداوتهم وكيدهم، ولا طاقة لفرد بحرب قوم إلا بالاعتماد على الله، الذي يراك حين تقوم في صلاتك وحدك، ويرى تقلّبك راكعاً وساجداً مع المصلين، فهو معك يسمع ويرى، إنه هو السميع العليم.", "h": ["تقرير التوحيد، وحرمة دعاء غير الله تعالى من سائر مخلوقاته، لأنه الشرك الحرام.", "من مات يدعو غير الله فهو معذّب لا محالة مع المعذّبين.", "تقرير قاعدة البدء بالأقارب في كل شيء، لأنهم ألصق بقريبهم من غيرهم.", "مشروعية لين الجانب والتواضع للمؤمنين، لا سيما حديثي العهد بالإسلام.", "وجوب البراءة من الشرك وأهله.", "وجوب التوكّل على الله والقيام بما أوجبه الله تعالى.", "فضل قيام الليل لما يحصل للعبد من معيّة الله تعالى."], "k": "«الذي يراك حين تقوم»… قيامي وحدي في الليل مرئيّ له؛ فهل يكفيني ذلك أنساً؟"}, {"lbl": "الآيات ٢٢١ – ٢٢٧", "q": "هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ ﴿٢٢١﴾ تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ ﴿٢٢٢﴾ يُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَٰذِبُونَ ﴿٢٢٣﴾ وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلۡغَاوُۥنَ ﴿٢٢٤﴾ أَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادٖ يَهِيمُونَ ﴿٢٢٥﴾ وَأَنَّهُمۡ يَقُولُونَ مَا لَا يَفۡعَلُونَ ﴿٢٢٦﴾ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَذَكَرُواْ ٱللَّهَ كَثِيرٗا وَٱنتَصَرُواْ مِنۢ بَعۡدِ مَا ظُلِمُواْۗ وَسَيَعۡلَمُ ٱلَّذِينَ ظَلَمُوٓاْ أَيَّ مُنقَلَبٖ يَنقَلِبُونَ ﴿٢٢٧﴾", "w": [["أنبّئكم", "أخبركم."], ["أفّاك أثيم", "كذّاب يقلب الكذب، غارق في الآثام."], ["يلقون السمع", "يصغون أشد الإصغاء للشياطين فيتلقّون منهم ما أكثره كذب وباطل."], ["الغاوون", "جمع غاوٍ: الضال عن الهدى، الفاسد القلب والنية."], ["في كل وادٍ", "من أودية الكلام وفنونه."], ["يهيمون", "يمضون في كل شِعب من الكلام، مدحاً أو ذمّاً، صدقاً أو كذباً."], ["يقولون ما لا يفعلون", "يقولون: فعلنا، وهم لم يفعلوا."], ["وانتصروا من بعد ما ظُلموا", "قالوا الشعر انتصاراً للحق، بأن ردّوا على من هجا الإسلام وأهله."], ["أيّ منقلب ينقلبون", "أيّ مرجع يرجعون إليه بعد الموت، وهو جهنم."]], "m": "لما ادّعى المبطلون أن الرسول ﷺ يتلقّى من الشياطين كما تتلقّى الكهّان ردّ تعالى: هل أنبّئكم على من تنزّل الشياطين؟ تنزّل على كل كذّاب يقلب الحقائق فيقول للظالم عادل وللخبيث طيب، كثير الآثام، فهذا الذي تلقي إليه الشياطين لكونه مثلها في ظلمة النفس وخبث الروح، أما محمد ﷺ فلم يُجرّب عليه كذب قط ولم يُعرف منه ذنب، فبطلت التهمة. والشياطين قبل أن يُحال بينهم وبين استراق السمع كانوا يصغون، وأكثرهم كاذبون، يخلطون مع الكلمة التي سمعوها مئة كذبة ويلقونها إلى إخوانهم من الكهنة. والشعراء يتّبعهم أهل الغواية، ألم تر أنهم في كل فن من الكلام يهيمون، يمدحون ويذمّون، ويقولون ما لا يفعلون؟ فلو كان محمد شاعراً لكان أتباعه غاوين، وأتباعه أهدى الناس وأصدقهم. ثم استثنى الذين آمنوا وعملوا الصالحات وذكروا الله كثيراً وانتصروا من بعد ما ظُلموا، كعبد الله بن رواحة وحسان بن ثابت، ينافحون عن الإسلام بشعرهم الصادق. وسيعلم الذين ظلموا الرسول والوحي أيّ مرجع يرجعون: إنه النار وبئس القرار.", "h": ["إبطال فرية المشركين من أن القرآن من جنس ما يقوله الكهّان.", "إبطال أن الرسول ﷺ كاهن وشاعر.", "بيان أن الشياطين تتّحد مع ذوي الأرواح الخبيثة بالإفك والآثام.", "بيان أن الشعراء المبطلين أتباعهم في كل زمان ومكان الغاوون الضالّون.", "جواز نظم الشعر وقوله في تقرير علم أو تسجيل حكمة، أو انتصار للإسلام والمسلمين بالردّ على من يهجوهم.", "التحذير من عاقبة الظلم، فإنها وخيمة."], "k": "«يقولون ما لا يفعلون»… كم من كلامي سبق فعلي؛ فهل أجعل اليوم فعلي يسبق قولي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 269;
insert into public.tdb_cards(topic, i, body) select 269, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١٣ – ٢٢٠", "q": "فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ ﴿٢١٣﴾ وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ ﴿٢١٤﴾ وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٢١٥﴾ فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ ﴿٢١٦﴾ وَتَوَكَّلۡ عَلَى ٱلۡعَزِيزِ ٱلرَّحِيمِ ﴿٢١٧﴾ ٱلَّذِي يَرَىٰكَ حِينَ تَقُومُ ﴿٢١٨﴾ وَتَقَلُّبَكَ فِي ٱلسَّـٰجِدِينَ ﴿٢١٩﴾ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٢٢٠﴾", "w": [["فلا تدع مع الله إلهاً آخر", "لا تعبد مع الله إلهاً آخر، لأن الدعاء هو العبادة."], ["وأنذر عشيرتك الأقربين", "وهم بنو هاشم وبنو عبد المطلب."], ["واخفض جناحك", "ألِن جانبك."], ["فإن عصوك", "أبوا قبول دعوتك إلى التوحيد."], ["فقل إني بريء مما تعملون", "من عبادة غير الله سبحانه."], ["الذي يراك حين تقوم", "إلى الصلاة فتصلي متهجّداً بالليل وحدك."], ["وتقلّبك في الساجدين", "ويرى تقلّبك مع المصلين راكعاً ساجداً قائماً."]], "m": "ما زال السياق في طلب هداية قريش: فلا تعبد مع الله إلهاً آخر فتكون من المعذّبين، وفيه تعريض بالمشركين، إذ إن كان الرسول يُنهى عن ذلك ويُتوعّد فغيره أولى. وأنذر عشيرتك الأقربين، أمره أن يخصّ قرابته بالإنذار أولاً لأنهم أولى بطلب النجاة لهم، وقد امتثل فنادى بطون قريش واحداً واحداً: لا أغني عنكم من الله شيئاً، حتى قال: يا فاطمة بنت محمد، سليني من مالي ما شئت، لا أغني عنك من الله شيئاً. وألِن جانبك للمؤمنين واعطف عليهم ليرسخ الإيمان في قلوبهم وهم في بداية الطريق، فإن عصاك من أُمرت بدعوتهم فقل: إني بريء من عبادتكم غير الله. وتوكّل على العزيز الرحيم، إذ البراءة من الشرك وأهله تقتضي عداوتهم وكيدهم، ولا طاقة لفرد بحرب قوم إلا بالاعتماد على الله، الذي يراك حين تقوم في صلاتك وحدك، ويرى تقلّبك راكعاً وساجداً مع المصلين، فهو معك يسمع ويرى، إنه هو السميع العليم.", "h": ["تقرير التوحيد، وحرمة دعاء غير الله تعالى من سائر مخلوقاته، لأنه الشرك الحرام.", "من مات يدعو غير الله فهو معذّب لا محالة مع المعذّبين.", "تقرير قاعدة البدء بالأقارب في كل شيء، لأنهم ألصق بقريبهم من غيرهم.", "مشروعية لين الجانب والتواضع للمؤمنين، ل